NAME = 'TpiKJPB: King Jems Pisin Baibel'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: '¶ Long stat Tok i stap, na Tok i stap wantaim God, na Tok em i God.',
        2: 'Em yet i stap long stat wantaim God.',
        3: 'Em i wokim olgeta samting. Na sapos em i no wokim, i no gat wanpela samting i kamap.',
        4: 'Insait long em laip i stap. Na dispela laip em i lait bilong ol man.',
        5: '¶ Na dispela lait i lait long tudak. Na tudak i no save long en.',
        6: 'God i salim wanpela man, husat nem bilong em em Jon.',
        7: 'Em yet i kam bilong stap wanpela witnes, long stap witnes long dispela Lait, inap long olgeta man, long wok bilong em, i ken bilip.',
        8: 'Em i no dispela Lait, tasol God i salim em long stap witnes bilong dispela Lait.',
        9: 'Dispela em i Lait tru, husat i givim lait long olgeta wan wan man husat i kam long dispela graun.',
        10: 'Em i stap long dispela graun, na em i wokim dispela graun, na dispela graun i no save long em.',
        11: 'Em i kam long lain bilong em yet, na lain bilong em yet i no kisim em.',
        12: 'Tasol hamas man i kisim em, long ol em i givim pawa long kamap ol pikinini man bilong God, yes, long ol husat i bilip long nem bilong em.',
        13: 'Husat i kamap nupela, i no long blut, o long laik bilong bodi, o long laik bilong man, tasol long God.',
        14: 'Na dispela Tok i kamap man, na stap namel long mipela, (na mipela i lukim glori bilong em, olsem glori bilong dispela wanpela tasol Papa i kamapim,) pulap long marimari na pasin i tru.',
        15: '¶ Jon i stap witnes bilong em, na singaut, i spik, Dispela em i em husat mi toktok, Em husat i kam bihain long mi God i laikim mobeta long mi. Long wanem, em i stap bipo long mi.',
        16: 'Na bilong pasin pulap bilong em yumi olgeta i bin kisim, na marimari bilong marimari.',
        17: 'Long wanem, God i givim lo long han bilong Moses, tasol marimari na pasin i tru i kam long han bilong Jisas Kraist.',
        18: 'I no gat man i bin lukim God long wanpela taim, dispela wanpela Pikinini Man tasol em i kamapim, husat i stap long bros bilong Papa, em i bin tokaut long em.',
        19: '¶ Na dispela em i tokaut bilong Jon, taim ol Ju i salim ol pris na ol lain Livai i lusim Jerusalem long askim em, Yu husat?',
        20: 'Na em i tok yes, na em i no tok nogat, tasol em i tok yes, Mi no Kraist.',
        21: 'Na ol i askim em, Wanem nau? Yu Ilaias? Na em i tok, Mi no Ilaias. Yu dispela profet? Na em i bekim tok, Nogat.',
        22: 'Nau ol i tokim em, Yu husat? Tokim mipela inap long mipela i ken bekim tok long ol husat i salim mipela. Yu tok wanem long yu yet?',
        23: 'Em i tok, Mi stap nek bilong wanpela i singaut long ples i no gat man, Mekim rot bilong Bikpela i stretpela, olsem profet Eseas i tok.',
        24: 'Na ol husat ol i salim i bilong ol Farisi.',
        25: 'Na ol i askim em, na tokim em, Bilong wanem yu givim baptais nau, sapos yu no stap dispela Kraist, o Ilaias, o dispela profet?',
        26: 'Na Jon i bekim tok long ol, i spik, Mi givim baptais wantaim wara. Tasol i gat wanpela i sanap namel long yupela, husat yupela i no save.',
        27: 'Em i dispela man, husat taim em i kam bihain long mi God i laikim mobeta long mi, husat mi no gat namba inap long lusim string bilong su bilong em.',
        28: 'Ol dispela samting i kamap long Betabara hapsait long Jordan, we Jon i givim baptais.',
        29: '¶ Long de bihain, Jon i lukim Jisas i kam long em, na em i tok, Lukim Pikinini Sipsip bilong God, husat i tekewe ol sin bilong ol manmeri bilong dispela graun.',
        30: 'Dispela em i em husat mi tok, Bihain long mi wanpela man i kam husat God i laikim mobeta long mi. Long wanem, em i stap bipo long mi.',
        31: 'Na mi no save long em. Tasol inap long em i ken kamap ples klia long Isrel, olsem na mi kam givim baptais wantaim wara.',
        32: 'Na Jon i stap witnes, i spik, Mi lukim Spirit i kam daun long heven olsem wanpela balus, na em i stap antap long em.',
        33: 'Na mi no save long em. Tasol em husat i salim mi long givim baptais wantaim wara, em yet i tokim mi, Antap long husat yu lukim Spirit i kam daun, na stap yet antap long em, em yet em em husat i givim baptais wantaim Holi Spirit.',
        34: 'Na mi lukim, na stap witnes long dispela em i Pikinini Man bilong God.',
        35: 'Na gen long de bihain Jon i sanap, na tupela disaipel bilong em.',
        36: 'Na taim em i lukim Jisas taim em i wokabaut, em i tok, Lukim Pikinini Sipsip bilong God!',
        37: '¶ Na tupela disaipel bilong em i harim em toktok, na ol i bihainim Jisas.',
        38: 'Nau Jisas i tanim, na lukim ol i bihainim em, na em i tok i go long tupela, Yutupela i painim wanem? Ol i tokim em, Rabai, (dispela em i tok olsem, taim yumi tanim, Tisa,) yu save stap we?',
        39: 'Em i tokim ol, Kam na lukim. Ol i kam na lukim we em i save stap, na ol i stap yet wantaim em long dispela de. Long wanem, em i klostu olsem long namba ten aua.',
        40: 'Wanpela bilong dispela tupela husat i harim Jon i toktok, na bihainim em, em Andru, brata bilong Saimon Pita.',
        41: 'Em i painim pinis pastaim brata bilong em yet Saimon, na tokim em, Mipela i bin painim pinis Mesaias, dispela em, taim yumi tanim, Kraist.',
        42: 'Na em i bringim em long Jisas. Na taim Jisas i lukim em, em i tok, Yu stap Saimon pikinini man bilong Jona. Ol bai kolim yu Sifas, dispela em, taim yumi tanim, Wanpela ston.',
        43: '¶ Long de bihain Jisas i gat laik long go insait long Galili, na em i painim pinis Filip, na tokim em, Bihainim mi.',
        44: 'Nau Filip em i bilong Betsaida, biktaun bilong Andru na Pita.',
        45: 'Filip i painim pinis Nataniel, na tokim em, Mipela i bin painim em pinis, bilong husat Moses long lo, na ol profet, i bin rait, Jisas bilong Nasaret, pikinini man bilong Josef.',
        46: 'Na Nataniel i tokim em, Ating i ken gat wanpela gutpela samting i ken kam ausait long Nasaret? Filip i tokim em, Kam na lukim.',
        47: 'Jisas i lukim Nataniel i kam long em, na toktok long sait bilong em, Lukim wanpela man Isrel tru, insait long husat i no gat gris tingting!',
        48: 'Nataniel i tokim em, Yu save long mi long we? Jisas i bekim na tokim em, Bipo long Filip i singautim yu, taim yu stap aninit long diwai fik, mi lukim yu.',
        49: 'Nataniel i bekim na tokim em, Rabai, yu stap Pikinini Man bilong God. Yu stap King bilong Israel.',
        50: 'Jisas i bekim na tokim em, Bikos mi tokim yu, mi lukim yu aninit long diwai fik, yu bilip? Yu bai lukim ol samting i bikpela moa long ol dispela samting.',
        51: 'Na em i tokim em, Tru tumas, tru tumas, mi tokim yu, Bihain long nau yupela bai lukim heven i op, na ol ensel bilong God i go antap na go daun antap long Pikinini Man bilong man.',
    },
    2: {
        1: '¶ Na namba tri de i gat wanpela marit long Kena bilong Galili. Na mama bilong Jisas i stap long dispela hap.',
        2: 'Na ol i singautim Jisas, na ol disaipel bilong em wantaim, long dispela marit.',
        3: 'Na taim ol i sot long wain, mama bilong Jisas i tokim em, Ol i no gat wain.',
        4: 'Jisas i tokim em, Meri, mi gat wanem wok wantaim yu? Aua bilong mi i no kamap yet.',
        5: 'Mama bilong em i tokim ol wokboi, Wanem samting em i tokim yupela, mekim dispela.',
        6: 'Na long dispela hap ol i putim sikispela sospen ston bilong wara, i bihainim pasin bilong kamap klin bilong ol Ju, na ol i holim tupela o tripela firkin wan wan.',
        7: 'Jisas i tokim ol, Pulimapim ol sospen bilong wara wantaim wara. Na ol i pulimapim ol i go inap long arere antap bilong ol.',
        8: 'Na em i tokim ol, Pulim i kam ausait nau, na karim i go long nambawan gavman bilong dispela bikpela kaikai. Na ol i karim dispela.',
        9: 'Taim hetman bilong dispela bikpela kaikai i bin testim dispela wara i kamap wain, na em i no save long em i bin kam long we, (tasol ol wokboi husat i pulim wara i save,) nambawan gavman bilong dispela bikpela kaikai i singautim man i laik marit,',
        10: 'Na tokim em, Olgeta wan wan man long stat i putim ol gutpela wain ausait, na taim ol man i bin dringim planti pinis, nau dispela samting i nogut moa. Tasol yu bin holim bek gutpela wain inap long nau.',
        11: 'Dispela stat bilong ol mirakel Jisas i mekim long Kena bilong Galili, na mekim glori bilong em kamap ples klia. Na ol disaipel bilong em i bilip long em.',
        12: '¶ Bihain long dispela em i go daun long Kaperneam, em, na mama bilong em, na ol brata bilong em, na ol disaipel bilong em. Na ol i no stap yet planti de long dispela hap.',
        13: 'Na pasova bilong ol Ju i laik kam klostu, na Jisas i go antap long Jerusalem,',
        14: 'Na em lukim insait long tempel ol husat i salim ol bulmakau man na ol sipsip na ol balus, na ol man bilong senisim mani i sindaun.',
        15: 'Na taim em i bin wokim wanpela wip wantaim ol liklik baklain, em i ranim ol olgeta i go ausait long tempel, na ol sipsip, na ol bulmakau man. Na em i kapsaitim ol mani bilong ol man bilong senisim mani, na tromoi ol tebol i go daun.',
        16: 'Na em i tokim ol husat i salim ol balus long mani, Kisim ol dispela samting i lusim hia. No ken mekim haus bilong Papa bilong mi wanpela haus bilong kago.',
        17: 'Na ol disaipel bilong em i tingim gen long dispela rait i stap pinis, Strongpela tingting long haus bilong yu i bin kaikai mi olgeta.',
        18: 'Nau ol Ju i bekim tok na tokim em, Yu soim wanem mak long mipela, taim mipela i luksave long yu wokim ol dispela samting?',
        19: 'Jisas i bekim na tokim ol, Bagarapim dispela tempel olgeta, na long tripela de mi bai kirapim dispela gen.',
        20: 'Nau ol Ju i tok, 46 yia ol i wok long wokim dispela tempel, na yu bai sanapim dispela long tripela de?',
        21: 'Tasol em i toktok long tempel bilong bodi bilong em.',
        22: 'Olsem na taim em i kirap bek pinis long dai, ol disaipel bilong em i tingim gen long em i bin toktok long dispela long ol. Na ol i bilipim rait bilong God, na dispela tok Jisas i bin toktok.',
        23: '¶ Nau taim em i stap long Jerusalem long pasova, long de bilong dispela bikpela kaikai, planti i bilip long nem bilong em, taim ol i lukim ol dispela mirakel em i mekim.',
        24: 'Tasol Jisas i no bin givim em yet long ol, bilong wanem, em i save long olgeta man,',
        25: 'Na em i no gat nid long wanpela i mas tokaut klia long man. Long wanem, em i save wanem samting i stap insait long man.',
    },
    3: {
        1: '¶ I gat wanpela man bilong ol Farisi i stap, nem bilong em em Nikodimas, wanpela hetman bilong ol Ju.',
        2: 'Em yet i kam long Jisas long nait, na tokim em, Rabai, mipela i save long yu wanpela tisa i kam long God. Long wanem, i no gat man i ken wokim ol dispela mirakel yu wokim, sapos God i no stap wantaim em.',
        3: 'Jisas i bekim na tokim em, Tru tumas, tru tumas, mi tokim yu, Sapos wanpela man i no kamap nupela gen, em i no inap lukim kingdom bilong God.',
        4: 'Nikodimas i tokim em, Olsem wanem mama i ken karim wanpela man taim em i lapun? Em i inap long go namba tu taim insait long bel bilong mama bilong em, na mama i ken karim em?',
        5: 'Jisas i bekim tok, Tru tumas, tru tumas, mi tokim yu, sapos wanpela man i no kamap nupela long wara na long Spirit, em i no inap go insait long kingdom bilong God.',
        6: 'Dispela samting bodi i karim em bodi. Na dispela samting Spirit i karim em spirit.',
        7: 'No ken tingting planti long mi tokim yu, Yupela i mas kamap nupela gen.',
        8: 'Win i ran we em i laik, na yu harim nois bilong en, tasol yu no inap save long em i kam we, na em i go we. Olsem tasol em olgeta wan wan husat i kamap nupela long Spirit.',
        9: 'Nikodimas i bekim na tokim em, Ol dispela samting i ken stap olsem wanem?',
        10: 'Jisas i bekim na tokim em, Yu wanpela tisa long Isrel, na ating i yes long yu no save long ol dispela samting?',
        11: 'Tru tumas, tru tumas, mi tokim yu, mipela i toktok long dispela samting mipela i save, na tokaut klia long dispela mipela i bin lukim. Na yupela i no kisim witnes bilong mipela.',
        12: 'Sapos mi bin tokim yupela long ol samting bilong dispela graun, na yupela i no bilip, yupela bai bilip olsem wanem, sapos mi tokim yupela long ol samting bilong heven?',
        13: 'Na i no gat man i bin go antap long heven, em husat i kam daun long heven tasol, yes, Pikinini Man bilong man husat i stap long heven.',
        14: 'Na olsem Moses i litimapim snek long ples i no gat man, yes, olsem tasol ol i mas litimapim Pikinini Man bilong man.',
        15: 'Inap long husat man i bilip long em i no ken lus olgeta, tasol i gat laip i stap gut oltaim oltaim.',
        16: 'Long wanem, God i laikim tru ol manmeri bilong dispela graun olsem, inap long em i givim dispela wanpela Pikinini Man tasol em i kamapim, long husat man i bilip long em i no ken lus olgeta, tasol em i gat laip i stap gut oltaim oltaim.',
        17: 'Long wanem, God i no salim Pikinini Man bilong em long dispela graun long mekim ol manmeri bilong dispela graun i lus long kot, tasol long em i ken kisim bek ol manmeri bilong dispela graun long wok bilong em.',
        18: 'Em husat i bilip long em i no lus long kot. Tasol em husat i no bilip em i lus pinis long kot, bilong wanem, em i no bin bilip long nem bilong dispela wanpela Pikinini Man bilong God tasol God i kamapim.',
        19: 'Na dispela em i as bilong ol man i lus long kot, long lait i kam long dispela graun, na ol man i laikim tru tudak mobeta long lait, bilong wanem, ol wok bilong ol i nogut.',
        20: 'Long wanem, olgeta wan wan husat i mekim pasin nogut i hetim lait, na tu em i no kam long lait, nogut lait i ken stretim ol wok bilong em.',
        21: 'Tasol em husat i mekim pasin i tru i kam long lait, inap long ol wok bilong em i ken kamap ples klia, long em i wokim ol insait long God.',
        22: '¶ Bihain long ol dispela samting Jisas i kam na ol disaipel bilong em insait long hap bilong Judia. Na long dispela hap em i stap yet wantaim ol, na givim baptais.',
        23: 'Na Jon tu i givim baptais long Inon klostu long Selim, bilong wanem, i gat planti wara long dispela hap. Na ol i kam, na kisim baptais.',
        24: 'Long wanem, ol i no bin tromoi Jon long kalabus yet.',
        25: 'Nau i gat askim i kirap namel long sampela bilong ol disaipel bilong Jon na ol Ju long sait bilong klinim.',
        26: 'Na ol i kam long Jon, na tokim em, Rabai, em husat i stap wantaim yu hapsait long Jordan, long husat yu stap witnes, lukim, em yet i givim baptais, na olgeta man i kam long em.',
        27: 'Jon i bekim na tok, Wanpela man i no inap kisim wanpela samting, sapos God i no givim em dispela i kam long heven.',
        28: 'Yupela yupela yet i stap witnes long mi, long mi tok, Mi no Kraist, tasol long God i salim mi i kam pas long em.',
        29: 'Em husat i gat meri i laik marit em man i laik marit. Tasol pren bilong man i laik marit, husat i sanap na harim em, i wokim bikpela amamas tru, bilong wanem, em i harim nek bilong man i laik marit. Olsem na dispela amamas tru bilong mi em inap pinis.',
        30: 'Em i mas go antap, tasol mi mas go daun.',
        31: 'Em husat i kam long antap em i antap olgeta. Em husat i bilong dispela graun em i bilong dispela graun, na i toktok long dispela graun. Em husat i kam long heven em i antap long olgeta samting.',
        32: 'Na wanem samting em i bin lukim na harim, dispela em i tokaut klia long en. Na i no gat man i kisim testimoni bilong em.',
        33: 'Em husat i bin kisim testimoni bilong em i bin putim long mak bilong em long God em i trupela.',
        34: 'Long wanem, em husat God i bin salim i toktok long ol tok bilong God. Long wanem, God i no givim Spirit long em long hap skel tasol.',
        35: 'Papa i laikim tru Pikinini Man, na em i bin givim olgeta samting i go long han bilong em.',
        36: 'Em husat i bilip long Pikinini Man i gat laip i stap gut oltaim oltaim. Na em husat i no bilip long Pikinini Man bai i no inap lukim laip, tasol belhat tru bilong God i stap antap long em.',
    },
    4: {
        1: '¶ Olsem na taim Bikpela i save long ol Farisi i bin harim long Jisas i kamapim na givim baptais long moa disaipel long Jon olsem wanem,',
        2: '(Maski Jisas em yet i no givim baptais, tasol ol disaipel bilong em,)',
        3: 'Em i lusim Judia, na go gen insait long Galili.',
        4: '¶ Na em i mas i gat nid long em i go namel long Samaria.',
        5: 'Nau em i kam long wanpela biktaun bilong Samaria, dispela ol i kolim Saikar, klostu long dispela hap graun Jekop i givim pikinini man bilong em Josef.',
        6: 'Nau hul wara bilong Jekop i stap long dispela hap. Olsem na Jisas, taim em i pilim les tru long wokabaut bilong em, i sindaun olsem antap long hul wara. Na em i klostu olsem long namba sikis aua.',
        7: 'I gat i kam wanpela meri bilong Samaria long pulim wara. Jisas i tokim em, Givim mi long dring.',
        8: '(Long wanem, ol disaipel bilong em i go pinis long biktaun bilong baim kaikai.)',
        9: 'Nau meri bilong Samaria i tokim em, Olsem wanem long yu, taim yu stap wanpela Ju, i askim dring long mi, husat em i wanpela meri bilong Samaria? Long wanem, ol Ju i no mekim ol samting wantaim ol lain Samaria.',
        10: 'Jisas i bekim na tokim em, Sapos yu save long presen bilong God, na em i husat husat i tokim yu, Givim mi long dring, yu bin gat laik long askim long em, na em i bin gat laik long givim yu wara i gat laip.',
        11: 'Meri i tokim em, Bikman, yu no gat wanpela samting long pulim wara, na hul wara i dip. Yu gat dispela wara i gat laip i kam long we nau?',
        12: 'Ating yu winim tumbuna papa bilong yumi Jekop, husat i givim yumi dispela hul wara, na husat i bin dring long en em yet, na ol pikinini bilong em, na ol bulmakau samting bilong em?',
        13: 'Jisas i bekim na tokim em, Husat man i dring long dispela wara bai nekdrai gen.',
        14: 'Tasol husat man i dring long dispela wara mi bai givim em bai i no inap nekdrai gen. Tasol dispela wara mi bai givim em bai stap insait long em wanpela hul wara i sut i kam antap i go long laip i stap gut oltaim oltaim.',
        15: 'Meri i tokim em, Bikman, givim mi dispela wara, inap long mi no ken nekdrai, o kam long hia long pulim wara.',
        16: 'Jisas i tokim em, Go, singautim man bilong yu, na kam long hia.',
        17: 'Meri i bekim na tok, Mi no gat man. Jisas i tokim em, Yu bin tok gut, Mi no gat man.',
        18: 'Long wanem, yu bin gat faipela man. Na em husat yu gat nau em i no man bilong yu. Long dispela yu bin tok tru.',
        19: 'Meri i tokim em, Bikman, mi kisim save long yu stap wanpela profet.',
        20: 'Ol tumbuna papa bilong mipela i lotu long dispela maunten. Na yupela i tok, long Jerusalem em i ples we ol man i mas lotu.',
        21: 'Jisas i tokim em, Meri, bilipim mi, aua i laik kamap, taim yupela bai i no inap lotuim Papa long dispela maunten, o yet long Jerusalem.',
        22: 'Yupela i no save wanem samting yupela i lotu. Mipela save wanem samting mipela i lotu. Long wanem, pasin bilong kisim bek em i bilong ol Ju.',
        23: 'Tasol aua i laik kamap, na nau i stap, taim ol man bilong lotu tru bai lotuim Papa long spirit na long pasin i tru. Long wanem, Papa i painim kain man long lotuim em.',
        24: 'God em i wanpela Spirit. Na ol husat i lotuim em i mas lotuim em long spirit na long pasin i tru.',
        25: 'Meri i tokim em, Mi save long Mesaias i laik kam, husat ol i kolim Kraist. Taim em i kam pinis, em bai tokim yumi long olgeta samting.',
        26: 'Jisas i tokim em, Mi husat i toktok long yu em em.',
        27: '¶ Na long dispela ol disaipel bilong em i kam, na tingting planti long em i toktok wantaim dispela meri. Tasol i no gat man i tok, Yu painim wanem? o, Bilong wanem yu toktok wantaim em?',
        28: 'Nau meri i lusim sospen bilong wara bilong em, na em i go long rot bilong em i go insait long biktaun, na tokim ol man,',
        29: 'Kam, lukim wanpela man, husat i tokim mi long olgeta samting mi mekim bipo. Ating i yes long dispela em i Kraist?',
        30: 'Nau ol i go ausait long biktaun, na kam long em.',
        31: 'Long dispela taim tu ol disaipel bilong em i askim em plis, i spik, Tisa, kaikai.',
        32: 'Tasol em i tokim ol, Mi gat kaikai long kaikai, dispela yupela i no save long en.',
        33: 'Olsem na ol disaipel bilong em i toktok wanpela i go long narapela, Ating wanpela man i bin bringim em samting long kaikai?',
        34: 'Jisas i tokim ol, Kaikai bilong mi em long mekim laik bilong em husat i salim mi, na long pinisim wok bilong em.',
        35: 'Ating i yes long yupela i tok, I gat fopela mun yet, na nau taim bilong kamautim kaikai i kam? Lukim, mi tokim yupela, Litimapim ol ai bilong yupela, na lukluk long ol bikpela gaden. Long wanem, ol i waitpela pinis long kamautim kaikai.',
        36: 'Na em husat i kamautim i kisim pe, na bungim ol kaikai i go long laip i stap gut oltaim oltaim. Inap long em husat i planim na em husat i kamautim wantaim i ken wokim amamas tru wantaim.',
        37: 'Na insait long dispela, dispela toktok em i tru, Wanpela i planim, na narapela i kamautim.',
        38: 'Mi salim yupela long kamautim kaikai we yupela i no bin wokim hatwok long en. Ol arapela man i bin hatwok, na yupela i go insait long ol hatwok bilong ol.',
        39: 'Na planti bilong ol lain Samaria bilong dispela biktaun i bilip long em long dispela toktok bilong dispela meri, husat i tokaut klia, Em i tokim mi long olgeta samting mi mekim bipo.',
        40: 'Olsem tasol taim ol lain Samaria i kam pinis long em, ol i askim em plis strong long em i ken stap yet wantaim ol. Na em i stap yet long dispela hap tupela de.',
        41: 'Na planti moa i bilip, bilong wanem, ol i harim tok bilong em yet.',
        42: 'Na ol i tokim meri, Nau mipela i bilip, i no bilong tingim toktok bilong yu. Long wanem, mipela i bin harim em mipela yet, na mipela save long em i tru long dispela em i Kraist, Man Bilong Kisim Bek bilong ol manmeri bilong dispela graun.',
        43: '¶ Nau bihain long tupela de em i lusim dispela hap, na go insait long Galili.',
        44: 'Long wanem, Jisas em yet i tokaut klia, long wanpela profet i no gat ona long kantri bilong em yet.',
        45: 'Nau taim em i kam insait long Galili, ol lain Galili i kisim em, taim ol i bin lukim olgeta dispela samting em i mekim long Jerusalem long dispela bikpela kaikai. Long wanem, ol tu i bin go antap long dispela bikpela kaikai.',
        46: 'Olsem tasol Jisas i kam gen long Kena bilong Galili, we em i bin mekim wara i kamap wain. Na long dispela hap i gat wanpela bikman, husat pikinini man bilong em i sik long Kaperneam.',
        47: 'Taim em i harim long Jisas i kam ausait long Judia i kam insait long Galili, em i go long em, na askim em plis strong long em i ken kam daun, na stretim sik bilong pikinini man bilong em. Long wanem, klostu tru em i laik dai.',
        48: 'Nau Jisas i tokim em, Sapos yupela i no lukim ol mak na ol samting bilong winim tingting, yupela i no laik bilip.',
        49: 'Dispela bikman i tokim em, Bikman, kam daun bipo pikinini bilong mi i dai.',
        50: 'Jisas i tokim em, Go long rot bilong yu. Pikinini man bilong yu i stap laip. Na man i bilipim dispela tok Jisas i bin toktok long em, na em i go long rot bilong em.',
        51: 'Na taim em i go daun nau, ol wokboi bilong em i bungim em, na tokim em, i spik, Pikinini man bilong yu i stap laip.',
        52: 'Nau em i askim long ol long em i wanem aua taim em i stat long kamap orait. Na ol i tokim em, Asde long namba seven aua skinhat i lusim em.',
        53: 'Olsem tasol papa i save long em i dispela aua stret, dispela long Jisas i tokim em, Pikinini man bilong yu i stap laip. Na em yet i bilip, na hauslain olgeta bilong em.',
        54: 'Dispela gen em i namba tu mirakel long Jisas i mekim, taim em i kam ausait long Judia i go insait long Galili.',
    },
    5: {
        1: '¶ Bihain long dispela i gat wanpela bikpela kaikai bilong ol Ju. Na Jisas i go antap long Jerusalem.',
        2: 'Nau i gat long Jerusalem klostu long maket bilong ol sipsip, wanpela liklik raunwara, dispela ol i kolim long tok ples Hibru Betesda, taim em i gat faipela veranda.',
        3: 'Long ol dispela wanpela bikpela lain tru bilong ol manmeri i no gat strong i slip, bilong ol aipas, ol manmeri i wokabaut kranki, ol manmeri i gat hanlek i drai, taim ol i wetim wara long muv.',
        4: 'Long wanem, wanpela ensel i go daun insait long dispela liklik raunwara long sampela taim God i makim, na tantanim dispela wara. Husat man nau i putim lek pastaim insait long wara bihain long wara i tantanim i kamap orait olgeta long wanem kain sik nogut em i gat.',
        5: 'Na wanpela man i stap long dispela hap, husat i gat wanpela sik 38 yia.',
        6: 'Taim Jisas i lukim em i slip, na save long em i bin stap nau longpela taim long dispela hevi, em i tokim em, Yu gat laik long kamap orait olgeta?',
        7: 'Dispela man i no gat strong i bekim tok long em, Bikman, mi no gat man, taim wara i tantanim, long putim mi insait long liklik raunwara. Tasol taim mi kam, narapela i putim lek i go daun bipo long mi.',
        8: 'Jisas i tokim em, Kirap, kisim bet bilong yu, na wokabaut.',
        9: 'Na wantu dispela man i kamap orait olgeta, na kisim bet bilong em, na wokabaut. Na long dispela de stret em i sabat.',
        10: 'Olsem na ol Ju i tokim em husat i kamap orait, Em i de sabat. Em i tambu long lo long yu long karim bet bilong yu.',
        11: 'Em i bekim tok long ol, Em husat i mekim mi orait olgeta, em stret i tokim mi, Kisim bet bilong yu i go antap, na wokabaut.',
        12: 'Nau ol i askim em, Dispela em i wanem man husat i tokim yu, Kisim bet bilong yu i go antap, na wokabaut?',
        13: 'Na em husat Jisas i oraitim i no save long em i husat. Long wanem, Jisas i bin karim em yet i go, taim wanpela bikpela lain tru i stap long dispela ples.',
        14: 'Bihain long en Jisas i lukim em long tempel, na tokim em, Lukim, yu kamap orait olgeta. No ken mekim sin moa, nogut wanpela samting i nogut moa i kam long yu.',
        15: 'Dispela man i lusim em, na tokim ol Ju long em i Jisas, husat i bin mekim em orait olgeta.',
        16: 'Na olsem na ol Ju i bin givim hevi long Jisas, na painim rot long kilim em i dai, bilong wanem, em i bin mekim ol dispela samting long de sabat.',
        17: '¶ Tasol Jisas i bekim tok long ol, Papa bilong mi wok inap long nau, na mi wok.',
        18: 'Olsem na ol Ju i painim rot moa long kilim em i dia, bilong wanem, em i no bin brukim sabat tasol, tasol tu em i tok long God em i Papa bilong em, na mekim em yet i wanmak stret wantaim God.',
        19: 'Nau Jisas i bekim na tokim ol, Tru tumas, tru tumas, mi tokim yupela, Pikinini Man i no ken wokim wanpela samting long em yet, tasol wanem samting em i lukim Papa i mekim. Long wanem, wanem samting olgeta em i mekim, ol dispela tu Pikinini Man i mekim wankain olsem.',
        20: 'Long wanem, Papa i laikim tru Pikinini Man, na soim em olgeta dispela samting em yet i wokim. Na em bai soim em ol bikpela wok moa long ol dispela, inap long yupela i ken tingting planti.',
        21: 'Long wanem, olsem Papa i kirapim ol daiman, na givim laip long ol, yes, olsem tasol Pikinini Man i givim laip long husat em i laik.',
        22: 'Long wanem, Papa i no jasim wanpela man, tasol em i bin putim olgeta kot long han bilong Pikinini Man.',
        23: 'Inap long olgeta man i ken givim ona long Pikinini Man, yes, olsem ol i givim ona long Papa. Em husat i no givim ona long Pikinini Man i no givim ona long Papa husat i bin salim em.',
        24: 'Tru tumas, tru tumas, mi tokim yupela, Em husat i harim tok bilong mi, na bilip long em husat i salim mi, i gat laip i stap gut oltaim oltaim, na em bai i no inap kamap lus long kot. Tasol em i lusim dai pinis i go long laip.',
        25: 'Tru tumas, tru tumas, mi tokim yupela, Aua i laik kam, na nau i stap pinis, taim ol daiman bai harim nek bilong Pikinini Man bilong God. Na ol husat i harim bai stap laip.',
        26: 'Long wanem, olsem Papa i gat laip insait long em yet, olsem tasol em i givim long Pikinini Man long gat laip insait long em yet.',
        27: 'Na em i bin givim em namba long mekim kot tu, bilong wanem, em i Pikinini Man bilong man.',
        28: 'No ken tingting planti long dispela. Long wanem, aua i laik kam, dispela long olgeta husat i stap long ol matmat bai harim nek bilong em,',
        29: 'Na ol bai kam ausait. Ol husat i bin mekim gutpela pasin, i go long kirap bek bilong laip. Na ol husat i bin mekim pasin nogut, i go long kirap bek bilong pe nogut bilong kot.',
        30: 'Mi no inap wokim wanpela samting long mi yet. Olsem mi harim, mi jasim. Na kot bilong mi i stretpela. Bilong wanem, mi no painim laik bilong mi yet, tasol laik bilong Papa husat i bin salim mi.',
        31: '¶ Sapos mi stap witnes bilong mi yet, witnes bilong mi i no tru.',
        32: 'I gat narapela husat i stap witnes bilong mi. Na mi save long witnes bilong em, dispela em i witnes long mi, em i tru.',
        33: 'Yupela i salim tok long Jon, na em i stap witnes bilong tok tru.',
        34: 'Tasol mi no kisim testimoni long man. Tasol ol dispela samting mi tok, inap long God i ken kisim bek yupela.',
        35: 'Em i wanpela lait i paia na i lait tru. Na yupela i gat laik long liklik taim long wokim amamas tru insait long lait bilong em.',
        36: 'Tasol mi gat wanpela witnes i winim dispela bilong Jon. Long wanem, ol dispela wok Papa i bin givim mi long pinisim, ol dispela wok stret mi mekim, ol i stap witnes bilong mi, long Papa i bin salim mi.',
        37: 'Na Papa em yet, husat i bin salim mi, i bin stap witnes bilong mi. Yupela i no bin harim nek bilong em wanpela taim, o lukim lukluk bilong em.',
        38: 'Na yupela i no gat tok bilong em i stap insait long yupela. Long wanem, husat em i bin salim, yupela i no bilipim em.',
        39: 'Painim tru long ol rait bilong God. Long wanem, insait long ol yupela i ting olsem yupela i gat laip i stap gut oltaim oltaim. Na ol em ol dispela i tokaut klia long mi.',
        40: 'Na yupela i no gat laik long kam long mi, inap long yupela i ken kisim laip.',
        41: 'Mi no kisim ona long ol man.',
        42: 'Tasol mi save long yupela, long yupela i no gat laikim tru bilong God insait long yupela.',
        43: 'Mi kam long nem bilong Papa bilong mi, na yupela i no kisim mi. Sapos narapela bai kam long nem bilong em yet, yupela bai kisim em.',
        44: 'Yupela i ken bilip olsem wanem, husat i kisim ona wanpela i kam long narapela, na yupela i no painim dispela ona i kam long God wanpela tasol?',
        45: 'No ken ting olsem mi bai sutim tok long yupela long Papa. I gat wanpela husat i sutim tok long yupela, yes Moses, long husat yupela i putim bilip.',
        46: 'Long wanem, sapos yupela i bin bilipim Moses, yupela i bin bilipim mi. Long wanem, em i raitim long mi.',
        47: 'Tasol sapos yupela i no bilipim ol rait bilong em, yupela bai bilipim ol toktok bilong mi olsem wanem?',
    },
    6: {
        1: '¶ Bihain long ol dispela samting Jisas i go hapsait long biksi Galili, dispela em biksi Tiberias.',
        2: 'Na wanpela bikpela lain tru i bihainim em, bilong wanem, ol i lukim ol dispela mirakel em i mekim long ol husat i gat sik nogut.',
        3: 'Na Jisas i go antap long wanpela maunten, na long dispela hap em i sindaun wantaim ol disaipel bilong em.',
        4: 'Na pasova, wanpela bikpela kaikai bilong ol Ju, i klostu.',
        5: 'Nau taim Jisas i litimapim tupela ai bilong em, na lukim wanpela bikpela lain i kam long em, em i tokim Filip, Yumi bai baim bret we, inap long ol dispela manmeri i ken kaikai?',
        6: 'Na dispela em i toktok long pruvim em. Long wanem, em em yet i save long em bai mekim wanem.',
        7: 'Filip i bekim tok long em, Bret yumi baim long 200 peni i no inap long inapim ol, inap long olgeta wan wan bilong ol i ken kisim liklik.',
        8: 'Wanpela bilong ol disaipel bilong em, Andru, brata bilong Saimon Pita, i tokim em,',
        9: 'I gat wanpela manki long hia, husat i gat faipela hap bret bali, na tupela liklik pis. Tasol ol i wanem namel long planti olsem?',
        10: 'Na Jisas i tok, Mekim ol man sindaun. Nau i gat planti gras long dispela ples. Olsem tasol ol man i sindaun, long namba klostu olsem 5,000.',
        11: 'Na Jisas i kisim ol hap bret. Na taim em i bin givim tok tenkyu, em i tilim long ol disaipel, na ol disaipel long ol husat i sindaun. Na wankain olsem long ol pis, hamas ol i gat laik long kisim.',
        12: 'Taim ol i pulap pinis, em i tokim ol disaipel bilong em, Bungim ol dispela hap hap i stap yet, inap long i no gat wanpela samting i lus.',
        13: 'Olsem na ol i bungim ol wantaim, na pulimapim twelpela basket wantaim ol hap hap bilong dispela faipela hap bret bali, dispela i stap yet antap na antap moa long ol husat i bin kaikai.',
        14: 'Nau ol dispela man, taim ol i bin lukim dispela mirakel Jisas i mekim, i tok, Dispela em tru long em i dispela profet i mas kam long dispela graun.',
        15: '¶ Olsem na taim Jisas i kisim save long ol i gat laik long kam na kisim em wantaim strong, long mekim em wanpela king, em i lusim ol gen i go long wanpela maunten em yet wanpela.',
        16: 'Na taim apinun tru i kam nau, ol disaipel bilong em i go daun long biksi,',
        17: 'Na go insait long wanpela sip, na go hapsait long biksi i go long Kaperneam. Na nau em i tudak, na Jisas i no kam long ol.',
        18: 'Na biksi i kirap bikos wanpela bikpela win i ran.',
        19: 'Olsem na taim ol i bin pul klostu olsem 25 o 30 furlong, ol i lukim Jisas i wokabaut antap long biksi, na em i wok long kam klostu long sip. Na ol i pret.',
        20: 'Tasol em i tokim ol, Em mi, no ken pret.',
        21: 'Nau ol i amamas long kisim em i kam insait long sip. Na wantu sip i stap long hap graun we ol i go.',
        22: '¶ Na de bihain, taim ol manmeri husat i sanap long hapsait bilong biksi i luksave long i no gat wanpela arapela bot long dispela hap, dispela wanpela we ol disaipel bilong em i bin go insait long en tasol, na long Jisas i no go wantaim ol disaipel bilong em long bot, tasol long ol disaipel i lusim em i stap wanpela na go,',
        23: '(Tasol i gat ol arapela bot i lusim Taibirias i kam klostu long ples we ol i bin kaikai bret, bihain long Bikpela i bin givim tok tenkyu,)',
        24: 'Olsem na taim ol manmeri i luksave long Jisas i no stap long dispela hap, o ol disaipel bilong em, ol tu i kalap long sip, na kam long Kaperneam, na painim Jisas.',
        25: 'Na taim ol i bin painim em pinis long hapsait bilong biksi, ol i tokim em, Rabai, wanem taim yu kam long hia?',
        26: 'Jisas i bekim ol na tok, Tru tumas, tru tumas, mi tokim yupela, Yupela i painim mi, i no bikos yupela i lukim ol mirakel, tasol bikos yupela i bin kaikai long ol hap bret, na yupela i pulap.',
        27: 'No ken hatwok long dispela kaikai i save pinis olgeta, tasol long dispela kaikai i stap yet i go inap long laip i stap gut oltaim oltaim, dispela Pikinini Man bilong man bai givim long yupela. Long wanem, God Papa i bin putim mak long em pinis.',
        28: '¶ Nau ol i tokim em, Mipela bai mekim wanem, inap long mipela i ken wokim ol wok bilong God?',
        29: 'Jisas i bekim na tokim ol, Dispela em i wok bilong God, long yupela i ken bilip long em husat em i bin salim.',
        30: 'Olsem na ol i tokim em, Wanem mak bai yu soim nau long mipela, inap long mipela i ken lukim, na bilipim yu? Yu wokim wanem wok?',
        31: 'Ol tumbuna papa bilong yumi i bin kaikai mana long ples i no gat man, olsem rait i stap pinis, Em i givim ol bret i kam long heven long kaikai.',
        32: 'Nau Jisas i tokim ol, Tru tumas, tru tumas, mi tokim yupela, Moses i no givim yupela dispela bret i kam long heven, tasol Papa bilong mi i givim yupela bret tru tru i kam long heven.',
        33: 'Long wanem, bret bilong God em em husat i kam daun long heven, na givim laip long ol manmeri bilong dispela graun.',
        34: 'Nau ol i tokim em, Bikpela, oltaim moa givim mipela dispela bret.',
        35: 'Na Jisas i tokim ol, Mi stap bret bilong laip. Em husat i kam long mi bai i no inap hangre gen. Na em husat i putim bilip long mi bai i no inap nekdrai gen.',
        36: 'Tasol mi tokim yupela, Long yupela tu i bin lukim mi, na yupela i no bilip.',
        37: 'Olgeta husat Papa i givim mi bai kam long mi. Na em husat i kam long mi bai mi no inap tru long rausim i go.',
        38: 'Long wanem, mi kam daun long heven, i no bilong wokim laik bilong mi yet, tasol laik bilong em husat i salim mi.',
        39: 'Na dispela em i laik bilong Papa husat i bin salim mi, long olgeta husat em i bin givim mi, mi no ken larim wanpela i lus, tasol mi mas kirapim em gen long las de.',
        40: 'Na dispela em i laik bilong em husat i salim mi, long olgeta wan wan husat i lukim Pikinini Man, na bilip long em, i ken gat laip i stap gut oltaim oltaim. Na mi bai kirapim em long las de.',
        41: 'Ol Ju nau i tok baksait long em, bilong wanem, em i tok, Mi stap dispela bret i kam daun long heven.',
        42: 'Na ol i tok, Ating i yes long dispela em i Jisas, pikinini man bilong Josef, husat papa na mama bilong em mipela i save? Olsem wanem nau long em i tok, Mi kam daun long heven?',
        43: 'Olsem na Jisas i bekim na tokim ol, No ken tok baksait namel long yupela yet.',
        44: 'I no gat man i ken kam long mi, sapos Papa husat i bin salim mi i no pulim em. Na mi bai kirapim em long las de.',
        45: 'Rait i stap pinis long ol profet, Na God bai skulim ol olgeta. Olsem na olgeta wan wan man husat i bin harim, na bin kisim skul long Papa, i kam long mi.',
        46: 'I no olsem long wanpela man i bin lukim Papa, em husat i bilong God tasol, em i bin lukim Papa.',
        47: 'Tru tumas, tru tumas, mi tokim yupela, em husat i putim bilip long mi i gat laip i stap gut oltaim oltaim.',
        48: 'Mi stap dispela bret bilong laip.',
        49: 'Ol tumbuna papa bilong yupela i bin kaikai mana long ples i no gat man, na ol i dai pinis.',
        50: 'Dispela em i dispela bret i kam daun long heven, long man i ken kaikai long en, na em i no inap dai.',
        51: 'Mi stap dispela bret i stap laip i kam daun long heven. Sapos wanpela man i kaikai long dispela bret, em bai stap laip oltaim oltaim. Na dispela bret mi bai givim, em i bodi bilong mi, dispela mi bai givim bilong laip bilong dispela graun.',
        52: 'Olsem na ol Ju i pait namel long ol yet, i spik, Dispela man i ken givim yumi bodi bilong em long kaikai olsem wanem?',
        53: 'Nau Jisas i tokim ol, Tru tumas, tru tumas, mi tokim yupela, Sapos yupela i no kaikai bodi bilong Pikinini Man bilong man, na dringim blut bilong em, yupela i no gat laip insait long yupela.',
        54: 'Husat man i kaikai bodi bilong mi, na dringim blut bilong mi, i gat laip i stap gut oltaim oltaim. Na mi bai kirapim em long las de.',
        55: 'Long wanem, bodi bilong mi em i kaikai tru, na blut bilong mi em i dring tru.',
        56: 'Em husat i kaikai bodi bilong mi, na dringim blut bilong mi, i stap insait long mi, na mi insait long em.',
        57: 'Olsem Papa i stap laip i bin salim mi, na mi stap laip long Papa, olsem tasol em husat i kaikai mi, yes, em bai stap laip long mi.',
        58: 'Dispela em i dispela bret, dispela i kam daun long heven. I no olsem ol tumbuna papa bilong yupela i bin kaikai mana, na ol i dai pinis. Em husat i kaikai long dispela bret bai stap laip oltaim oltaim.',
        59: 'Ol dispela samting em i tok insait long sinagog, taim em i skulim ol long Kaperneam.',
        60: '¶ Olsem na planti bilong ol disaipel bilong em, taim ol i bin harim dispela, i tok, Dispela em i wanpela hatpela tok. Husat i ken harim dispela?',
        61: 'Taim Jisas i save insait long em yet long ol disaipel bilong em i tok baksait long dispela, em i tokim ol, Dispela i bagarapim bel bilong yupela?',
        62: 'Wanem na sapos yupela bai lukim Pikinini Man bilong man i go antap we em i stap bipo?',
        63: 'Em i spirit husat i givim laip. Bodi i no helpim liklik. Ol dispela toktok mi tokim yupela, ol i spirit, na ol i laip.',
        64: 'Tasol i gat sampela bilong yupela husat i no bilip. Long wanem, Jisas i save long stat long ol i husat husat i no bilip, na husat bai putim em long han bilong birua.',
        65: 'Na em i tok, Olsem na mi tokim yupela, long i no gat man i ken kam long mi, sapos Papa bilong mi i no givim dispela long em.',
        66: 'I stat long dispela taim planti bilong ol disaipel bilong em i go bek, na ol i no wokabaut moa wantaim em.',
        67: 'Nau Jisas i tokim dispela twelpela, Yupela i gat laik tu long go?',
        68: 'Nau Saimon Pita i bekim tok long em, Bikpela, mipela bai go long husat? Yu gat ol toktok bilong laip i stap gut oltaim oltaim.',
        69: 'Na mipela i bilip na save tru long yu stap dispela Kraist, Pikinini Man bilong God i stap laip.',
        70: 'Jisas i bekim tok long ol, Ating i yes long mi bin makim yupela twelpela, na wanpela bilong yupela em i wanpela spirit nogut?',
        71: 'Em i toktok long Judas Iskariot, pikinini man bilong Saimon. Long wanem, em i em husat bai putim em long han bilong birua, taim em i stap wanpela bilong dispela twelpela.',
    },
    7: {
        1: '¶ Bihain long ol dispela samting Jisas i wokabaut long Galili. Long wanem, em i no gat laik long wokabaut long hap bilong ol Ju, bilong wanem, ol Ju i painim rot long kilim em i dai.',
        2: 'Nau dispela bikpela kaikai bilong ol haus win bilong ol Ju i kam klostu.',
        3: 'Olsem na ol brata bilong em i tokim em, Lusim hia, na go long Judia, inap long ol disaipel bilong yu tu i ken lukim ol dispela wok yu mekim.',
        4: 'Long wanem, i no gat man husat i mekim wanpela samting hait, na em em yet i painim rot long ol man i ken save long em ples klia. Sapos yu wokim ol dispela samting, soim yu yet long ol manmeri bilong dispela graun.',
        5: 'Long wanem, ol brata bilong em tu i no bin bilip long em.',
        6: 'Nau Jisas i tokim ol, Taim bilong mi i no kam yet. Tasol taim bilong yupela em i redi olgeta taim.',
        7: 'Dispela graun i no inap hetim yupela. Tasol em i hetim mi, bilong wanem, mi tokaut klia long en, long ol wok bilong en i nogut.',
        8: 'Yupela go antap long dispela bikpela kaikai. Mi no go antap yet long dispela bikpela kaikai. Long wanem, taim bilong mi i no kam pulap yet.',
        9: 'Taim em i bin tokim ol dispela toktok long ol, em i stap yet long Galili.',
        10: 'Tasol taim ol brata bilong em i go antap pinis, nau em tu i go antap long dispela bikpela kaikai, i no ples klia, tasol samting olsem samting hait.',
        11: 'Nau ol Ju i painim em long dispela bikpela kaikai, na tok, em i stap we?',
        12: 'Na i gat planti tok baksait namel long ol manmeri long sait bilong em. Long wanem, sampela i tok, Em i gutpela man. Ol arapela i tok, Nogat. Tasol em i giamanim ol manmeri.',
        13: 'Tasol i no gat man i toktok ples klia long sait bilong em, long wanem, ol i pret long ol Ju.',
        14: '¶ Nau klostu long namel bilong dispela bikpela kaikai Jisas i go antap long tempel, na skulim ol manmeri.',
        15: 'Na ol Ju i tingting planti, i spik, Dispela man i save long ol leta olsem wanem, taim em i no bin lainim?',
        16: 'Jisas i bekim ol, na tok, Skul bilong mi i no bilong mi, tasol bilong em husat i salim mi.',
        17: 'Sapos wanpela man i gat laik long mekim laik bilong em, em bai save long skul, sapos em i bilong God, o sapos mi toktok long mi yet.',
        18: 'Em husat i toktok long sait bilong em yet i painim glori bilong em yet. Tasol em husat i painim glori bilong em husat i salim em, em yet em i trupela, na i no gat pasin i no stretpela i stap insait long em.',
        19: 'Ating i yes long Moses i givim lo long yupela, na yet i no gat wanpela bilong yupela i bihainim lo? Bilong wanem yupela i go nabaut long kilim mi i dai?',
        20: 'Ol manmeri i bekim na tok, Yu gat wanpela spirit nogut. Husat i go nabaut long kilim yu i dai?',
        21: 'Jisas i bekim na tokim ol, Mi bin wokim wanpela wok, na yupela olgeta i tingting planti.',
        22: 'Olsem na Moses i givim pasin bilong katim skin long yupela, (i no bikos em i bilong Moses, tasol bilong ol tumbuna papa,) na yupela long de sabat i katim skin bilong man.',
        23: 'Sapos ol i katim skin bilong wanpela man long de sabat, inap long lo bilong Moses i no ken bruk, ating yupela i kros long mi, bilong wanem, mi bin mekim wanpela man orait olgeta long de sabat?',
        24: 'No ken jasim bilong bihainim lukluk bilong en, tasol jasim bilong bihainim stretpela kot.',
        25: 'Nau sampela bilong Jerusalem i tok, Ating i yes long dispela em i em, husat ol i painim rot long kilim i dai?',
        26: 'Tasol, harim, em i no pret long toktok, na ol i no toktok long em long wanpela toktok. Ating i yes long ol hetman i save tru long dispela em i Kraist tru?',
        27: 'Tasol mipela save long dispela man em i kam we. Tasol taim Kraist i kam, i no gat man i save long em i kam we.',
        28: 'Nau Jisas i singaut insait long tempel taim em i skulim ol, i spik, Yupela i save long mi, na yupela i save long mi kam we wantaim. Na mi no kam long tingting bilong mi yet, tasol em husat i salim mi em trupela, husat yupela i no save.',
        29: 'Tasol mi save long em. Long wanem, mi kam long em, na em i bin salim mi.',
        30: 'Nau ol i painim rot long kisim em. Tasol i no gat man i putim ol han long em, bilong wanem, aua bilong em i no kamap yet.',
        31: 'Na planti bilong ol manmeri i bilip long em, na tok, Taim Kraist i kam, bai em i wokim ol mirakel moa long ol dispela samting dispela man i bin wokim?',
        32: 'Ol Farisi i harim long ol manmeri i tok baksait long ol kain samting long sait bilong em. Na ol Farisi na ol bikpris i salim ol ofisa long kisim em.',
        33: 'Nau Jisas i tokim ol, Liklik taim yet bai mi stap wantaim yupela, na nau mi bai go long em husat i salim mi.',
        34: 'Yupela bai painim mi, na bai yupela i no inap lukim mi. Na ples we mi stap, long dispela hap yupela i no inap kam.',
        35: 'Nau ol Ju i tok namel long ol yet, Em bai go we, inap long mipela bai i no inap lukim em? Em bai go long ol Ju i bruk nabaut namel long ol lain i no Ju, na skulim ol lain i no Ju?',
        36: 'Dispela em i wanem kain toktok long em i tok, Yupela bai painim mi, na bai yupela i no inap lukim mi, na we mi stap, long dispela hap yupela i no inap kam?',
        37: '¶ Long las de, dispela bikpela de bilong dispela bikpela kaikai, Jisas i sanap na singaut, i spik, Sapos wanpela man i nekdrai, larim em kam long mi, na dring.',
        38: 'Em husat i bilip long mi, olsem rait bilong God i bin tok, ausait long bel bilong em ol riva bilong wara i gat laip bai ran.',
        39: '(Tasol dispela em i tok long sait bilong Spirit, husat ol husat i bilip long em bai kisim. Long wanem, God i no givim Holi Spirit yet, bikos Jisas i no bin kisim glori yet.)',
        40: 'Olsem na planti bilong ol manmeri, taim ol harim dispela tok, i tok, Em i tru dispela em i dispela Profet.',
        41: 'Sampela arapela i tok, Dispela em Kraist. Tasol sampela i tok, Kraist bai kam ausait long Galili?',
        42: 'Ating i yes long rait bilong God i bin tok, Long Kraist i kam long tumbuna pikinini bilong Devit, na ausait long taun bilong Betlehem, we Devit i bin stap?',
        43: 'Olsem tasol em i as bilong i gat bruk namel long ol manmeri.',
        44: 'Na sampela bilong ol i gat laik long kisim em. Tasol i no gat man i putim ol han antap long em.',
        45: '¶ Nau ol ofisa i kam long ol bikpris na ol Farisi. Na ol i tokim ol, Bilong wanem yupela i no bin bringim em?',
        46: 'Ol ofisa i bekim tok, I no gat man bipo i toktok olsem dispela man.',
        47: 'Nau ol Farisi i bekim tok long ol, Ating yupela tu i bilipim tok giaman?',
        48: 'Ating wanpela bilong ol hetman o bilong ol Farisi i bin bilip long em?',
        49: 'Tasol dispela lain manmeri husat i no save long lo i lus olgeta long kot.',
        50: 'Nikodimas i tokim ol, (em husat i kam long Jisas long nait, na em i stap wanpela bilong ol,)',
        51: 'Ating lo bilong yumi i jasim wanpela man, bipo em i harim em, na save long wanem samting em i mekim?',
        52: 'Ol i bekim na tokim em, Ating yu tu i bilong Galili? Painim tru, na lukluk. Long wanem, i no gat wanpela profet i kirap i kam ausait long Galili.',
        53: 'Na olgeta wan wan man i go long haus bilong em yet.',
    },
    8: {
        1: '¶ Jisas i go long maunten bilong ol Oliv.',
        2: 'Na long moning tru em i kam gen long tempel, na olgeta manmeri i kam long em. Na em i sindaun, na skulim ol.',
        3: 'Na ol man bilong rait na ol Farisi i bringim long em wanpela meri ol i kisim taim em i bagarapim marit long pasin pamuk. Na taim ol i bin putim em long ples namel,',
        4: 'Ol i tokim em, Tisa, mipela i kisim dispela meri taim em i bagarapim marit long pamuk pasin, long taim stret em i wokim.',
        5: 'Nau insait long lo Moses i tok strong long yumi, long yumi mas tromoi ston long kilim kain meri. Tasol yu tok wanem?',
        6: 'Dispela ol i tok, taim ol traim em, inap long ol i ken gat as bilong sutim tok long em. Tasol Jisas i lindaun, na rait long graun wantaim pinga bilong em, olsem em i no harim ol.',
        7: 'Olsem tasol taim ol i wok long askim yet long em, em i litimapim em yet, na tokim ol, Em husat i no gat sin namel long yupela, larim em pastaim tromoi ston long meri.',
        8: 'Na gen em i lindaun, na rait long graun.',
        9: 'Na ol husat i harim dispela, taim mausbel bilong ol yet i sutim bel bilong ol, i go ausait wanpela i bihain long arapela, i stat long man i lapun moa, yes, i go inap long las man. Na ol i lusim Jisas i stap wanpis, na dispela meri i sanap namel long ples.',
        10: 'Taim Jisas i bin litimapim em yet, na em i no lukim wanpela arapela, dispela meri tasol i stap, em i tokim em, Meri, ol dispela man i sutim tok long yu i stap we? Ating i yes long i no gat man i sutim tok long yu?',
        11: 'Em i tok, I no gat man, Bikpela. Na Jisas i tokim em, Mi tu i no sutim tok long yu. Go, na no ken mekim sin moa.',
        12: '¶ Nau Jisas i toktok gen long ol, i spik, Mi stap lait bilong dispela graun. Em husat i bihainim mi bai i no inap wokabaut long tudak, tasol em bai i gat lait bilong laip.',
        13: 'Olsem na ol Farisi i tokim em, Yu stap witnes long yu yet. Witnes bilong yu i no tru.',
        14: 'Jisas i bekim na tokim ol, Maski mi stap witnes long mi yet, yet witnes bilong mi em i tru. Long wanem, mi save mi kam long we, na mi go we. Tasol yupela i no inap save long mi kam we, na mi go we.',
        15: 'Yupela i jasim i bihainim bodi. Mi no jasim wanpela man.',
        16: 'Na yet sapos mi jasim, kot bilong mi i tru. Long wanem, mi no stap wanpis, tasol mi na Papa husat i salim mi i stap.',
        17: 'Rait i stap pinis tu insait long lo bilong yupela, long testimoni bilong tupela man em i tru.',
        18: 'Mi stap wanpela husat i stap witnes bilong mi yet, na Papa husat i salim mi i stap witnes bilong mi.',
        19: 'Nau ol i tokim em, Papa bilong yu i stap we? Jisas i bekim tok, Yupela i no save long mi, o Papa bilong mi. Sapos yupela i bin save long mi, yupela i mas bin save long Papa bilong mi tu.',
        20: 'Ol dispela toktok Jisas i tok long bakstua bilong ol samting i dia tru, taim em i skulim ol long tempel. Na i no gat man i putim ol han antap long em. Long wanem, aua bilong em i no kamap yet.',
        21: '¶ Nau Jisas i tok gen long ol, Mi go long rot bilong mi, na yupela bai painim mi, na yupela bai dai long ol sin bilong yupela. We mi go, yupela i no inap kam.',
        22: 'Nau ol Ju i tok, Em bai kilim em yet i dai? Bilong wanem, em i tok, We mi go, yupela i no inap kam.',
        23: 'Na em i tokim ol, Yupela i bilong daunbilo. Mi bilong antap. Yupela i bilong dispela graun. Mi no bilong dispela graun.',
        24: 'Olsem na mi tokim yupela, long yupela bai dai long ol sin bilong yupela. Long wanem, sapos yupela i no bilip long mi stap dispela man, yupela bai dai long ol sin bilong yupela.',
        25: 'Nau ol i tokim em, Yu husat? Na Jisas i tokim ol, Yes, em stret husat mi tokim yupela long stat.',
        26: 'Mi gat planti samting long tokim na jasim long yupela. Tasol em husat i salim mi em i trupela. Na mi toktok long ol manmeri bilong dispela graun long ol dispela samting, dispela mi bin harim long em.',
        27: 'Ol i no kisim save long em i tokim ol long Papa.',
        28: 'Nau Jisas i tokim ol, Taim yupela i bin litimapim Pikinini Man bilong man, nau bai yupela i save long mi stap dispela man, na long mi no wokim wanpela samting long mi yet. Tasol olsem Papa bilong mi i bin skulim mi, mi toktok long ol dispela samting.',
        29: 'Na em husat i salim mi i stap wantaim mi. Papa i no bin lusim mi i stap wanpis. Long wanem, olgeta taim mi mekim ol dispela samting i amamasim em.',
        30: 'Taim em i toktok long ol dispela toktok, planti i bilip long em.',
        31: '¶ Nau Jisas i tokim ol dispela Ju husat i bilip long em, Sapos yupela i stap yet long tok bilong mi, orait yupela i stap ol disaipel tru bilong mi.',
        32: 'Na yupela bai save long tok tru, na tok tru bai mekim yupela fri.',
        33: 'Ol i bekim tok long em, Mipela i stap ol tumbuna pikinini bilong Ebraham, na i no gat taim mipela i bin stap slev bilong wanpela man. Olsem wanem yu tok, Yupela bai kamap fri?',
        34: 'Jisas i bekim tok long ol, Tru tumas, tru tumas, mi tokim yupela, Husat man i mekim sin em i wokboi bilong sin.',
        35: 'Na wokboi i no stap long haus oltaim oltaim. Tasol Pikinini Man i stap oltaim oltaim.',
        36: 'Olsem na sapos Pikinini Man bai mekim yupela fri, yupela bai stap fri tru.',
        37: 'Mi save long yupela i stap tumbuna pikinini bilong Ebraham. Tasol yupela painim rot long kilim mi i dia, bilong wanem, tok bilong mi i no gat ples insait long yupela.',
        38: '¶ Mi toktok long dispela samting mi bin lukim wantaim Papa bilong mi. Na yupela i mekim dispela samting yupela i bin lukim wantaim papa bilong yupela.',
        39: 'Ol i bekim na tokim em, Ebraham em i papa bilong mipela. Jisas i tokim ol, Sapos yupela i stap ol pikinini bilong Ebraham, yupela bai wokim ol wok bilong Ebraham.',
        40: 'Tasol nau yupela i painim rot long kilim mi i dia, wanpela man husat i bin tokim yupela long tok tru, dispela mi bin harim long God. Ebraham i no mekim dispela.',
        41: 'Yupela i wokim ol wok bilong papa bilong yupela. Nau ol i tokim em, Mama i no karim mipela long pamuk pasin. Mipela i gat wanpela Papa, yes, God.',
        42: 'Jisas i tokim ol, Sapos God em i Papa bilong yupela, yupela bai laikim mi tru. Long wanem, mi kam ausait na kam long God. Na tu mi no kam long mi yet, tasol em i salim mi.',
        43: 'Bilong wanem yupela i no kisim save long toktok bilong mi? Yes, bilong wanem, yupela i no inap long harim tok bilong mi.',
        44: 'Yupela i bilong papa bilong yupela Seten, na ol aigris bilong papa bilong yupela yupela bai mekim. Em i man bilong kilim man i dai long stat, na em i no stap insait long tok tru, bilong wanem, i no gat tok tru insait long em. Taim em i toktok long wanpela giaman, em i toktok long em yet. Long wanem, em i man bilong giaman, na papa bilong en.',
        45: 'Na bikos mi tokim yupela long tok tru, yupela i no bilipim mi.',
        46: '¶ Husat bilong yupela i soim tru tru sin bilong mi? Na sapos mi tok long tok tru, bilong wanem yupela i no bilipim mi?',
        47: 'Em husat i bilong God i harim ol toktok bilong God. Olsem na yupela i no harim ol, bilong wanem, yupela i no bilong God.',
        48: 'Nau ol Ju i bekim, na tokim em, Ating i yes long mipela i toktok gut long yu stap wanpela man Samaria, na yu gat wanpela spirit nogut?',
        49: 'Jisas i bekim tok, Mi no gat wanpela spirit nogut. Tasol mi givim ona long Papa bilong mi, na yupela daunim nem bilong mi.',
        50: 'Mi no painim glori bilong mi yet. I gat wanpela husat i painim na jasim.',
        51: '¶ Tru tumas, tru tumas, mi tokim yupela, Sapos wanpela man i bihainim tok bilong mi, em bai i no inap lukim dai.',
        52: 'Nau ol Ju i tokim em, Nau mipela i save long yu gat wanpela spirit nogut. Ebraham i dai pinis, na ol profet. Na yu tok, Sapos wanpela man i bihainim tok bilong mi, em bai i no inap testim dai.',
        53: 'Ating yu bikpela moa long papa bilong yumi Ebraham, husat i dai pinis? Na ol profet i dai pinis. Yu mekim yu yet husat?',
        54: 'Jisas i bekim tok, Sapos mi givim ona long mi yet, ona bilong mi em samting nating. Em i Papa bilong mi husat i givim ona long mi, long husat yupela i tok, long em i God bilong yupela.',
        55: 'Yupela yet i no bin save long em. Tasol mi save long em. Na sapos mi bai tok, Mi no save long em, mi bai stap wanpela man bilong giaman wankain olsem yupela. Tasol mi save long em, na mi bihainim tok bilong em.',
        56: 'Papa bilong yupela Ebraham i wokim amamas tru bilong lukim de bilong mi. Na em i lukim pinis, na em i amamas.',
        57: 'Nau ol Ju i tokim em, Yu no gat 50 krismas yet, na yu bin lukim Ebraham?',
        58: 'Jisas i tokim ol, Tru tumas, tru tumas, mi tokim yupela, Bipo Ebraham i stap, mi stap.',
        59: 'Nau ol i kisim ol ston long tromoi long em. Tasol Jisas i haitim em yet, na go ausait long tempel, na go namel long namel bilong ol, na olsem tasol abrusim ol.',
    },
    9: {
        1: '¶ Na taim Jisas abrusim ol, em i lukim wanpela man husat i aipas i stat long taim mama i karim em.',
        2: 'Na ol disaipel bilong em i askim em, i spik, Tisa, husat i mekim sin, dispela man, o papamama bilong em, inap long mama i karim em aipas?',
        3: 'Jisas i bekim tok, Dispela man i no bin mekim sin, o papamama bilong em. Tasol em i aipas inap long ol wok bilong God i ken kamap ples klia insait long em.',
        4: 'Mi mas wokim ol wok bilong em husat i salim mi, taim em i san yet. Nait i kam, taim i no gat man i inap wok.',
        5: 'Taim mi stap yet long dispela graun, mi stap lait bilong dispela graun.',
        6: 'Taim em i bin toktok olsem, em i spet long graun, na wokim graun i wet long dispela spet, na em i makim tupela ai bilong aipas man wantaim dispela graun i wet,',
        7: 'Na tokim em, Go, waswas long liklik raunwara bilong Siloam, (ol i tanim dispela tok, Salim.) Olsem na em i go long rot bilong em, na waswas, na kam taim tupela ai bilong em i ken lukluk.',
        8: '¶ Olsem na ol man i stap klostu long em, na ol husat bipo i bin lukim em long em i aipas, i tok, Ating i yes long dispela em i em husat i sindaun na pulim mani?',
        9: 'Sampela i tok, Dispela em em. Ol arapela i tok, Em i olsem em. Tasol em i tok, Mi stap dispela man.',
        10: 'Olsem na ol i tokim em, Tupela ai bilong yu i op olsem wanem?',
        11: 'Em i bekim na tok, Wanpela man husat ol i kolim Jisas i wokim graun i wet, na makim tupela ai bilong mi, na tokim mi, Go long liklik raunwara bilong Siloam, na waswas. Na mi go na waswas, na mi kisim strong bilong lukluk.',
        12: 'Nau ol i tokim em, Em i stap we? Em i tok, Mi no save.',
        13: '¶ Ol i bringim long ol Farisi em husat long taim bipo em i aipas.',
        14: 'Na em i de sabat taim Jisas i wokim graun i wet, na opim tupela ai bilong em.',
        15: 'Nau gen ol Farisi tu i askim em long em i bin kisim strong bilong lukluk olsem wanem. Em i tokim ol, Em i putim graun i wet antap long tupela ai bilong mi, na mi waswas, na mi ken lukluk.',
        16: 'Olsem na sampela bilong ol Farisi i tok, Dispela man i no bilong God, bilong wanem, em i no bihainim de sabat. Ol arapela i tok, Olsem wanem wanpela man husat i sinman i ken wokim ol kain mirakel? Na i gat wanpela bruk namel long ol.',
        17: 'Ol i tokim aipas man gen, Yu tok wanem long em, long em i bin opim tupela ai bilong yu? Em i tok, Em i wanpela profet.',
        18: 'Tasol ol Ju i no bin bilip long sait bilong em, long em i bin aipas, na em i kisim strong bilong lukluk, inap long ol i singautim papamama bilong em husat i bin kisim strong bilong lukluk.',
        19: 'Na ol i askim tupela, i spik, Dispela em i pikinini man bilong yupela, husat yupela i tok em i aipas taim mama i karim em? Nau em i ken lukluk olsem wanem?',
        20: 'Papamama bilong em i bekim ol na tok, Mipela i save long dispela em i pikinini man bilong mipela, na long em i aipas taim mama i karim em.',
        21: 'Tasol long wanem rot em i ken lukluk nau, mipela i no save. O husat i bin opim tupela ai bilong em, mipela i no save. Em i bikpela pinis, askim em. Em bai toktok long sait bilong em yet.',
        22: 'Ol dispela toktok papamama bilong em i tok, bilong wanem, ol i pret long ol Ju. Long wanem, ol Ju i bin gat wanbel tingting pinis, long sapos wanpela man i bin tok yes long em i Kraist, ol bai rausim em long sinagog.',
        23: 'Olsem na papamama bilong em i tok, Em i bikpela pinis, askim em.',
        24: 'Nau gen ol i singautim dispela man husat i aipas bipo, na tokim em, Givim biknem long God. Mipela i save long dispela man em i wanpela sinman.',
        25: 'Em i bekim na tok, Sapos em i stap wanpela sinman o nogat, mi no save. Wanpela samting mi save, long, we mi stap aipas olsem bipo, nau mi ken lukluk.',
        26: 'Nau ol i tokim em gen, Em i mekim wanem long yu? Em i opim tupela ai bilong yu olsem wanem?',
        27: 'Em i bekim tok long ol, Mi bin tokim yupela pinis, na yupela i no harim. Olsem wanem na yupela i gat laik long harim dispela gen? Yupela tu bai stap ol disaipel bilong em?',
        28: 'Nau ol i sutim tok nogut long em, na tok, Yu stap disaipel bilong em. Tasol mipela i stap ol disaipel bilong Moses.',
        29: 'Mipela i save long God i toktok long Moses. Long sait bilong dispela man, mipela i no save long em i kam long we.',
        30: 'Man i bekim na tokim ol, Insait long dispela em i wanpela samting bilong tingting planti long en, long yupela i no save long em i kam long we, na yet em i bin opim tupela ai bilong mi.',
        31: 'Nau yumi save long God i no harim ol sinman. Tasol sapos wanpela man i stap man bilong lotuim God, na mekim laik bilong em, em i harim em.',
        32: 'I stat long taim dispela graun i stat i no gat wanpela taim long yumi harim long wanpela man i opim tupela ai bilong wanpela husat i aipas taim mama i karim em.',
        33: 'Sapos dispela man i no bilong God, em i no inap mekim wanpela samting.',
        34: 'Ol i bekim na tokim em, Mama i karim yu long ol sin olgeta, na ating yu laik skulim mipela, a? Na ol i rausim em i go ausait.',
        35: '¶ Jisas i harim long ol i bin rausim em i go ausait. Na taim em i bin painim em pinis, em i tokim em, Yu bilip long Pikinini Man bilong God?',
        36: 'Em i bekim na tok, em i husat, Bikpela, inap long mi ken bilip long em?',
        37: 'Na Jisas i tokim em, Yu bin lukim em pinis, na em i dispela husat i toktok wantaim yu wantaim.',
        38: 'Na em i tok, Bikpela, mi bilip. Na em i lotuim em.',
        39: '¶ Na Jisas i tok, Mi kam long dispela graun bilong wokim kot, inap long ol husat i no inap lukluk i ken lukluk. Na long ol husat i lukluk i ken kamap aipas.',
        40: 'Na sampela bilong ol Farisi husat i stap wantaim em i harim ol dispela toktok, na ol i tokim em, Ating mipela tu i aipas?',
        41: 'Jisas i tokim ol, Sapos yupela i aipas, bai yupela i no gat sin. Tasol nau yupela i tok, Mipela i lukluk. Olsem na sin bilong yupela i stap yet.',
    },
    10: {
        1: '¶ Tru tumas, tru tumas, Mi tokim yupela, em husat i no go long dua insait long haus sipsip, tasol em i kalapim long wanpela arapela rot, em yet em i wanpela stilman na raskol stilman.',
        2: 'Tasol em husat i go insait long dua em i wasman bilong sipsip.',
        3: 'Wasman bilong dua i opim dua long em. Na ol sipsip i harim nek bilong em. Na em i kolim ol sipsip bilong em long nem, na stiaim ol i go ausait.',
        4: 'Na taim em i putim sipsip bilong em i go ausait, em i go pas long ol, na ol sipsip i bihainim em. Long wanem, ol i save long nek bilong em.',
        5: 'Na ol i no inap bihainim wanpela ausait man, tasol ol bai ranawe long em. Long wanem, ol i no save long nek bilong ol ausait man.',
        6: 'Dispela tok piksa Jisas i tokim ol. Tasol ol i no kisim save long ol dispela samting em i tokim ol em i wanem samting.',
        7: 'Nau Jisas i tokim ol gen, Tru tumas, tru tumas, mi tokim yupela, Mi stap dua bilong sipsip.',
        8: 'Olgeta tru husat i bin kam bipo long mi em ol stilman na ol raskol stilman. Tasol ol sipsip i no bin harim ol.',
        9: 'Mi dispela dua. Long mi sapos wanpela man i go insait, God bai kisim bek em, na em bai go insait na ausait, na lukim ples gras.',
        10: 'Stilman i no kam long narapela as, bilong stilim tasol, na long kilim, na long bagarapim olgeta. Mi kam inap long ol i ken gat laip, na long ol i ken gat dispela i planti moa yet.',
        11: 'Mi stap gutpela wasman bilong sipsip. Gutpela wasman bilong sipsip i givim laip bilong em bilong helpim sipsip.',
        12: 'Tasol em husat i wok long pe tasol, na em i no wasman bilong sipsip, husat ol sipsip i no bilong em yet, i lukim wolf i kam, na em i lusim ol sipsip, na ranawe. Na wolf i kisim ol, na brukim ol sipsip i go nabaut.',
        13: 'Man i wok long pe tasol i ranawe, bilong wanem, em i man i wok long pe tasol, na em i no wari long ol sipsip.',
        14: 'Mi gutpela wasman bilong sipsip, na mi save long ol sipsip bilong mi, na ol sipsip bilong mi i save long mi.',
        15: 'Olsem Papa i save long mi, yes, olsem tasol mi save long Papa. Na mi givim laip bilong mi long helpim ol sipsip.',
        16: 'Na mi gat sampela arapela sipsip, husat i no bilong dispela haus sipsip. Ol tu mi mas bringim, na ol bai harim nek bilong mi. Na bai i gat wanpela haus sipsip i stap, na wanpela wasman bilong sipsip.',
        17: 'Olsem na Papa bilong mi i laikim mi tru, bilong wanem, mi givim laip bilong mi, inap long mi ken kisim dispela gen.',
        18: 'I no gat man i tekewe dispela long mi, tasol mi givim dispela long mi yet. Mi gat pawa bilong givim dispela, na mi gat pawa bilong kisim dispela gen. Dispela tok strong mi bin kisim long Papa bilong mi.',
        19: '¶ Olsem na i gat wanpela bruk gen namel long ol Ju long ol dispela toktok.',
        20: 'Na planti bilong ol i tok, Em i gat wanpela spirit nogut, na em i longlong. Bilong wanem yupela i harim em?',
        21: 'Ol arapela i tok, Ol dispela em i no toktok bilong em husat i gat wanpela spirit nogut. Wanpela spirit nogut em inap long opim ol ai bilong aipas man?',
        22: '¶ Na long Jerusalem em i dispela bikpela kaikai bilong makim, na em i taim bilong bikpela kol.',
        23: 'Na Jisas i wokabaut insait long tempel long veranda bilong Solomon.',
        24: 'Nau ol Ju i kam raun nabaut long em, na tokim em, Inap long wanem taim yu bai mekim mipela stap long tupela tingting? Sapos yu stap dispela Kraist, tokim mipela klia.',
        25: 'Jisas i bekim tok long ol, Mi tokim yupela pinis, na yupela i no bilip. Ol dispela wok mi wokim long nem bilong Papa bilong mi, ol i stap witnes bilong mi.',
        26: 'Tasol yupela i no bilip, bilong wanem, yupela i no bilong ol sipsip bilong mi, olsem mi tokim yupela.',
        27: 'Ol sipsip bilong mi i harim nek bilong mi, na mi save long ol, na ol i bihainim mi.',
        28: 'Na mi givim ol laip i stap gut oltaim oltaim. Na ol bai i no inap lus, na tu i no gat wanpela man bai kamautim ol ausait long han bilong mi.',
        29: 'Papa bilong mi, husat i givim ol long mi, i winim olgeta. Na i no gat man husat i inap long kamautim ol ausait long han bilong Papa bilong mi.',
        30: 'Mi na Papa bilong mi i wanpela.',
        31: 'Nau ol Ju i kisim ol ston gen long tromoi ston long kilim em.',
        32: 'Jisas i bekim tok long ol, Planti gutpela wok mi bin soim yupela i kam long Papa bilong mi. Bilong wanem bilong ol dispela wok yupela i tromoi ston long kilim mi?',
        33: 'Ol Ju i bekim em, i spik, Bilong wanpela gutpela wok mipela i no tromoi ston long kilim yu, tasol bilong tok bilas, na bikos yu, taim yu stap man, yu mekim yu yet God.',
        34: 'Jisas i bekim tok long ol, Ating i yes long rait i stap pinis long lo bilong yupela, Mi tok, Yupela i stap ol god?',
        35: 'Sapos em i kolim ol ol god, long husat tok bilong God i bin kam, na rait bilong God i no inap bruk,',
        36: 'Ating yupela i tok long sait bilong em, husat Papa i bin mekim i kamap holi, na salim em long dispela graun, Yu tok bilas, bikos mi tok, Mi Pikinini Man bilong God?',
        37: 'Sapos mi no wokim ol wok bilong Papa bilong mi, no ken bilipim mi.',
        38: 'Tasol sapos mi mekim olsem, maski yupela i no bilipim mi, bilipim ol wok, inap long yupela i ken save, na bilip, long Papa i stap insait long mi, na mi insait long em.',
        39: '¶ Olsem na ol i painim rot gen long kisim em. Tasol em i ranawe i go ausait long han bilong ol,',
        40: 'Na em i go gen hapsait long Jordan i go long ples we Jon i givim baptais pastaim. Na long dispela hap em i stap.',
        41: 'Na planti i kam long em, na tok, Jon i no wokim mirakel. Tasol olgeta dispela samting Jon i toktok long sait bilong dispela man em i tru.',
        42: 'Na planti i bilip long em long dispela hap.',
    },
    11: {
        1: '¶ Nau wanpela man em i sik, husat nem bilong em em Lasaras, bilong Betani, taun bilong Maria na susa bilong em Marta.',
        2: '(Em i dispela Maria husat i makim Bikpela wantaim wel i gat marasin, na klinim tupela fut bilong em wantaim gras bilong em, husat brata bilong em Lasaras i sik.)',
        3: 'Olsem na ol susa bilong em i salim tok long em, i spik, Bikpela, lukim, em husat yu laikim tru em i sik.',
        4: 'Taim Jisas i harim dispela, em i tok, Dispela sik i no go long dai, tasol em i bilong glori bilong God, inap long Pikinini Man bilong God i ken kisim glori long en.',
        5: 'Nau Jisas i laikim tru Marta, na susa bilong em, na Lasaras.',
        6: 'Olsem na taim em i bin harim long em i sik, em i stap tupela de yet long ples stret we em i stap.',
        7: 'Nau bihain long en em i tokim ol disaipel bilong em, Yumi go long Judia gen.',
        8: 'Ol disaipel bilong em i tokim em, Tisa, nau tasol ol Ju i painim rot long tromoi ston long kilim yu, na yu go long dispela hap gen?',
        9: 'Jisas i bekim tok, Ating i yes long i gat twelpela aua long san? Sapos wanpela man i wokabaut long san, em i no sutim lek, bilong wanem, em i lukim lait bilong dispela graun.',
        10: 'Tasol sapos wanpela man i wokabaut long nait, em i sutim lek, bilong wanem, i no gat lait insait long em.',
        11: 'Ol dispela samting em i tok. Na bihain long dispela em i tokim ol, Pren bilong yumi Lasaras i slip. Tasol mi go, inap long mi ken kirapim em long slip.',
        12: 'Nau ol disaipel bilong em i tok, Bikpela, sapos em i slip, em bai stap gutpela.',
        13: 'Tasol Jisas i toktok long dai bilong em. Tasol ol i ting long em i bin toktok long kisim malolo long slip.',
        14: 'Nau Jisas i tokim ol klia, Lasaras i dai pinis.',
        15: 'Na mi amamas long sait bilong yupela long mi no stap long dispela hap, inap long dispela as, long yupela i ken bilip. Tasol yumi go long em.',
        16: 'Nau Tomas i tok, husat ol i kolim Didimas, i go long ol poroman disaipel bilong em, Yumi go tu, inap long yumi ken dai wantaim em.',
        17: '¶ Nau taim Jisas i kam, em i luksave long em i bin slip long matmat fopela de pinis.',
        18: 'Nau Betani i stap klostu long Jerusalem, klostu olsem 15 furlong long en.',
        19: 'Na planti bilong ol Ju i kam long Marta na Maria, long givim bel isi long tupela long sait bilong brata bilong tupela.',
        20: 'Nau Marta, long taim stret long em i harim long Jisas wok long i kam, i go na bungim em. Tasol Maria i sindaun yet long haus.',
        21: 'Nau Marta i tokim Jisas, Bikpela, sapos yu bin stap long hia, brata bilong mi i no bin dai.',
        22: 'Tasol mi save, yes, long nau, wanem samting yu laik askim long God, God bai givim dispela long yu.',
        23: 'Jisas i tokim em, Brata bilong yu bai kirap bek gen.',
        24: 'Marta i tokim em, Mi save long em bai kirap bek gen long kirap bek gen bilong dispela las de.',
        25: 'Jisas i tokim em, Mi stap kirap bek, na laip. Em husat i bilip long mi, maski em i dai pinis, yet bai em i stap laip.',
        26: 'Na husat man i stap laip na bilip long mi bai i no inap dai. Yu bilipim dispela?',
        27: 'Em i tokim em, Yes, Bikpela. Mi bilip long yu stap dispela Kraist, Pikinini Man bilong God, husat i mas kam long dispela graun.',
        28: 'Na taim em i bin tok olsem, em i go long rot bilong em, na singautim susa bilong em Maria hait, i spik, Tisa i kam pinis, na em i singautim yu.',
        29: 'Long taim stret long em i harim dispela, em i kirap kwiktaim, na kam long em.',
        30: 'Nau Jisas i no kam insait yet long taun, tasol em i stap yet long dispela ples we Marta i bungim em.',
        31: 'Nau ol Ju husat i stap wantaim meri long haus, na givim bel isi long em, taim ol i lukim Maria, long em i kirap hariap na go ausait, ol i bihainim em, i spik, Em i go long matmat long krai tru long dispela hap.',
        32: 'Nau taim Maria i kam we Jisas i stap, na lukim em, em i pundaun long tupela lek bilong em, i spik long em, Bikpela, sapos yu bin stap long hia, brata bilong mi i no bin dai.',
        33: '¶ Olsem na taim Jisas i lukim em i krai tru, na ol Ju tu i krai tru husat i kam wantaim em, em i krai wantaim pen insait long spirit, na em i pilim wari,',
        34: 'Na tok, Yupela i bin slipim em we? Ol i tokim em, Bikpela, kam na lukim.',
        35: 'Jisas i krai tru.',
        36: 'Nau ol Ju i tok, Lukim, em i laikim em tru moa!',
        37: 'Na sampela bilong ol i tok, Ating i yes long dispela man, husat i opim ol ai bilong ol aipas, em i inap long mekim, yes, long dispela man i no mas bin dai?',
        38: 'Olsem na taim Jisas i krai wantaim pen gen insait long em yet, i kam long matmat. Em i wanpela hul i go insait long maunten, na wanpela ston i slip antap long en.',
        39: 'Jisas i tok, Yupela tekewe dispela ston. Marta, susa bilong em husat i dai pinis, i tokim em, Bikpela, long dispela taim nau em i sting pinis. Long wanem, em i bin stap daiman fopela de.',
        40: 'Jisas i tokim em, Ating i yes long mi tokim yu, long, sapos yu bai bilip, yu bai lukim glori bilong God?',
        41: 'Nau ol i tekewe dispela ston long ples we daiman i slip. Na Jisas i litimapim tupela ai bilong em, na tok, Papa, mi tok tenkyu long yu long yu bin harim mi.',
        42: 'Na mi save long yu harim mi olgeta taim. Tasol bilong tingim ol manmeri husat i sanap klostu mi toktok olsem, inap long ol i ken bilip long yu bin salim mi.',
        43: 'Na taim em i bin toktok olsem, em i singaut wantaim bikpela nek, Lasaras, kam ausait.',
        44: 'Na em husat i dai pinis i kam ausait, pas wantaim ol klos bilong matmat long han na lek. Na pes bilong em i pas nabaut wantaim wanpela liklik laplap. Jisas i tokim ol, Lusim em, na larim em i go.',
        45: '¶ Nau planti bilong ol Ju husat i kam long Maria, na i bin lukim ol dispela samting Jisas i mekim, i bilip long em.',
        46: 'Tasol sampela bilong ol i go long ol rot bilong ol long ol Farisi, na tokim ol long wanem ol samting Jisas i bin mekim.',
        47: 'Nau ol bikpris na ol Farisi i bungim wanpela kaunsil, na tok, Yumi mekim wanem? Long wanem, dispela man i wokim planti mirakel.',
        48: 'Sapos yumi larim em i stap olsem, olgeta man bai bilip long em. Na ol man Rom bai kam na tekewe ples na kantri bilong yumi wantaim.',
        49: 'Na wanpela bilong ol, husat nem bilong em em Kaiafas, taim em i stap hetpris long dispela yia stret, i tokim ol, Yupela i no save long wanpela samting liklik,',
        50: 'O tingim na skelim long em i gutpela bilong helpim yumi, long wanpela man i mas dai bilong helpim ol manmeri, na long dispela kantri olgeta i no ken pinis olgeta.',
        51: 'Na em i no toktok long dispela long em yet. Tasol taim em i stap hetpris dispela yia, em i autim tok profet long Jisas i mas dai bilong helpim dispela kantri.',
        52: 'Na i no bilong dispela kantri tasol, tasol tu long em bai bungim wantaim long wanpela, olgeta pikinini bilong God husat i bruk nabaut ausait.',
        53: 'Nau long dispela de i go ol i kisim tok helpim wantaim bilong mekim em i dai.',
        54: 'Olsem na Jisas i no wokabaut moa long ples klia namel long ol Ju. Tasol em i go long dispela taim long wanpela hap graun i klostu long ples i no gat man, insait long wanpela biktaun ol i kolim Ifraim, na long dispela hap em i stap yet wantaim ol disaipel bilong em.',
        55: 'Na pasova bilong ol Ju i stap klostu. Na planti i go ausait long hap i no gat planti man i go antap long Jerusalem bipo long pasova, long klinim ol yet.',
        56: 'Nau ol i painim Jisas, na toktok namel long ol yet, taim ol i sanap long tempel, Yupela i ting wanem, long em bai i no inap kam long dispela bikpela kaikai?',
        57: 'Nau ol bikpris na ol Farisi wantaim i bin givim tok strong, long, sapos wanpela man i save long em i stap we, em i mas soim dispela, inap long ol i ken holimpas em.',
    },
    12: {
        1: '¶ Nau Jisas, sikispela de bipo long pasova, i kam long Betani, we Lasaras i stap husat i bin stap daiman, husat em i kirapim long dai.',
        2: 'Long dispela hap ol i wokim wanpela apinun kaikai long em. Na Marta i wokim wok. Tasol Lasaras i wanpela bilong ol husat i sindaun long tebol wantaim em.',
        3: 'Nau Maria i kisim wanpela paun bilong wel i gat marasin bilong spaiknard, i dia tru, na em i makim tupela fut bilong Jisas, na klinim tupela fut bilong em wantaim gras bilong em. Na haus i pulap wantaim smel bilong dispela wel i gat marasin',
        4: 'Nau wanpela bilong ol disaipel bilong em, Judas Iskariot, pikinini man bilong Saimon, husat bai putim em long han bilong birua, i tok,',
        5: 'Bilong wanem em i no salim dispela wel i gat marasin long 300 pens, na givim long ol rabisman?',
        6: 'Dispela em i tok, i no long em i wari long ol rabisman, tasol bikos em i wanpela stilman, na em i holim bek, na karim wanem samting ol i putim insait long en.',
        7: 'Nau Jisas i tok, Larim meri i stap. Long redi long de bilong planim mi em i bin holimpas dispela.',
        8: 'Long wanem, yupela i gat ol rabisman wantaim yupela olgeta taim. Tasol yupela i no gat mi olgeta taim.',
        9: 'Olsem na planti manmeri bilong ol Ju i save long em i stap long dispela hap. Na ol i no kam bilong tingim Jisas tasol, tasol long ol i ken lukim Lasaras tu, husat em i bin kirapim long dai.',
        10: 'Tasol ol bikpris i painim tingting long ol i ken mekim Lasaras i dai tu,',
        11: 'Bikos em i as bilong planti bilong ol Ju i go lusim ol, na bilip long Jisas.',
        12: '¶ Long de bihain planti manmeri husat i kam long dispela bikpela kaikai, taim ol i harim long Jisas i kam long Jerusalem,',
        13: 'I kisim ol han bilong diwai palmen, na go ausait long bungim em, na singaut, Hosana. Blesing i stap long King bilong Isrel husat i kam long nem bilong Bikpela.',
        14: 'Na Jisas, taim em i bin painim pinis wanpela yangpela donki, i sindaun antap long en, olsem rait i stap pinis,',
        15: 'No ken pret, pikinini meri bilong Saion. Lukim, King bilong yu i kam, na sindaun antap long pikinini bilong donki.',
        16: 'Ol dispela samting ol disaipel bilong em i no kisim save long en pastaim. Tasol taim Jisas i kisim glori pinis, nau ol i tingim gen long ol dispela samting ol i raitim long em, na long ol i bin mekim ol dispela samting long em.',
        17: 'Olsem na ol manmeri husat i stap wantaim em taim em i singautim Lasaras long kam ausait long matmat bilong em, na kirapim em long dai, i stap witnes long en.',
        18: 'Long dispela as ol manmeri tu i bungim em, bikos ol i harim long em i bin wokim dispela mirakel.',
        19: 'Olsem na ol Farisi i toktok namel long ol yet, Yupela i kisim save long yupela i no win long wanpela samting olsem wanem? Lukim, ol manmeri bilong dispela graun i go bihainim em.',
        20: '¶ Na long dispela hap i gat sampela Grik namel long ol husat i kam antap long lotu long dispela bikpela kaikai.',
        21: 'Olsem na ol yet i kam long Filip, husat i bilong Betsaida bilong Galili, na askim em, i spik, Bikman, mipela i gat laik long lukim Jisas.',
        22: 'Filip i kam na tokim Andru. Na gen Andru na Filip i tokim Jisas',
        23: 'Na Jisas i bekim ol, i spik, Aua i kam pinis, long Pikinini Man bilong man i mas kisim glori.',
        24: 'Tru tumas, tru tumas, mi tokim yupela, Sapos pikinini kaikai bilong wit i no pundaun insait long graun na dai, em i stap wanpis. Tasol sapos em i dai, em i karim planti kaikai.',
        25: 'Em husat i laikim tru laip bilong em bai lusim dispela. Na em husat i hetim laip bilong em long dispela graun bai holimpas dispela inap long laip i stap gut oltaim oltaim.',
        26: 'Sapos wanpela man i wokim wok wokboi long mi, larim em bihainim mi. Na we mi stap, long dispela hap tu wokboi bilong mi bai stap. Sapos wanpela man i wokim wok wokboi long mi, Papa bilong mi bai givim ona long em.',
        27: '¶ Nau tewel bilong mi i pilim wari. Na mi bai tok wanem, Papa, kisim bek mi long dispela aua? Long dispela as tasol mi kam long dispela aua.',
        28: 'Papa, givim glori long nem bilong yu. Nau i gat wanpela nek i kam long heven, i spik, Mi bin givim glori long en, na mi bai givim glori long en gen wantaim.',
        29: 'Olsem na ol manmeri, husat i sanap klostu, na harim dispela, i tok long klaut i pairap. Ol arapela i tok, Wanpela ensel i toktok long em.',
        30: 'Jisas i bekim na tok, Dispela nek i no kam bilong helpim mi, tasol bilong helpim yupela.',
        31: 'Nau kot i kam long dispela graun. Nau God bai tromoi hetman bilong dispela graun i go ausait.',
        32: 'Na mi, sapos ol i litimapim mi i lusim dispela graun, mi bai pulim olgeta man i kam long mi.',
        33: 'Dispela em i tok, bilong mekim klia wanem kain dai em i mas dai long en.',
        34: 'Ol manmeri i bekim tok long em, Mipela i bin harim ausait long lo long Kraist i stap oltaim oltaim. Na olsem wanem yu tok, Ol i mas litimapim Pikinini Man bilong man? Dispela Pikinini Man bilong man em i husat?',
        35: 'Nau Jisas i tokim ol, Liklik taim yet lait i stap wantaim yupela. Wokabaut taim yupela i gat dispela lait, nogut tudak i kam antap long yupela. Long wanem, em husat i wokabaut long tudak i no save long em i go we.',
        36: 'Taim yupela i gat lait, bilip long dispela lait, inap long yupela i ken stap ol pikinini bilong lait. Ol dispela samting Jisas i tok, na lusim ol, na em i bin haitim em yet long ol.',
        37: '¶ Tasol maski em i bin mekim planti mirakel olsem long ai bilong ol, yet ol i no bilip long em.',
        38: 'Inap long toktok bilong profet Eseas i ken kamap pinis, dispela em i tok, Bikpela, husat i bin bilipim ripot bilong mipela? Na han bilong Bikpela i bin kamap ples klia long husat?',
        39: 'Olsem na ol i no inap long bilip, bikos Eseas i tok gen,',
        40: 'Em i bin aipasim ol ai bilong ol, na strongim bel bilong ol, inap long ol i no ken lukluk wantaim ol ai bilong ol, o kisim save wantaim bel bilong ol, na senisim bilip, na mi ken oraitim ol.',
        41: 'Ol dispela samting Eseas i tok, taim em i lukim glori bilong em, na toktok long sait bilong em.',
        42: '¶ Tasol namel long ol nambawan hetman tu planti i bilip long em. Tasol bilong tingim ol Farisi ol i no bin tok yes long em, nogut ol i ken rausim ol long sinagog.',
        43: 'Long wanem, ol i laikim tru ol biknem i kam long ol man moa long biknem i kam long God.',
        44: '¶ Jisas i singaut na tok, Em husat i bilip long mi, em i no bilip long mi, tasol long em husat i salim mi.',
        45: 'Na em husat i lukim mi i lukim em husat i salim mi.',
        46: 'Mi kam wanpela lait insait long dispela graun, long husat man i bilip long mi bai i no ken stap long tudak.',
        47: 'Na sapos wanpela man i harim ol toktok bilong mi, na em i no bilip, mi no jasim em. Long wanem, mi no kam long jasim dispela graun, tasol long kisim bek dispela graun.',
        48: 'Em husat i tok nogat olgeta long mi, na i no kisim ol toktok bilong mi, i gat wanpela husat i jasim em. Dispela tok mi bin toktok, dispela stret bai jasim em long las de.',
        49: 'Long wanem, mi no bin toktok long laik bilong mi yet. Tasol Papa husat i salim mi, em i givim mi wanpela tok strong, long mi mas tok wanem, na long wanem samting mi mas toktok.',
        50: 'Na mi save long tok strong bilong em em i laip i stap gut oltaim oltaim. Olsem na wanem samting mi toktok, yes, olsem Papa i tokim mi, olsem tasol mi toktok.',
    },
    13: {
        1: '¶ Nau bipo long dispela bikpela kaikai bilong pasova, taim Jisas i save long aua bilong em i kam pinis long em i mas lusim dispela graun i go long Papa, taim em i bin laikim tru ol dispela bilong em yet husat i stap long dispela graun, em i laikim ol tru inap long pinis.',
        2: 'Na taim apinun kaikai i pinis, Seten nau i putim insait long bel bilong Judas Iskariot, pikinini man bilong Saimon, long putim em long han bilong birua.',
        3: 'Taim Jisas i save long Papa i bin givim olgeta samting i go long tupela han bilong em, na long em i kam long God, na em i go long God,',
        4: 'Em i kirap i lusim apinun kaikai, na slipim ol klos bilong em long sait. Na em i kisim wanpela laplap, na pasim nabaut namel bilong em yet.',
        5: 'Bihain long dispela em i kapsaitim wara long wanpela traipela dis, na em i stat long wasim ol fut bilong ol disaipel, na long klinim ol wantaim dispela laplap we em i pas nabaut wantaim dispela.',
        6: 'Nau em i kam long Saimon Pita. Na Pita i tokim em, Bikpela, ating yu wasim tupela fut bilong mi?',
        7: 'Jisas i bekim na tokim em, Wanem samting mi mekim yu no save long en nau. Tasol yu bai save long en bihain long nau.',
        8: 'Pita i tokim em, Bai i no gat taim long yu wasim tupela fut bilong mi. Jisas i bekim tok long em, Sapos mi no wasim yu, yu no gat hap wantaim mi.',
        9: 'Saimon Pita i tokim em, Bikpela, i no tupela fut bilong mi tasol, tasol tu tupela han bilong mi na het bilong mi.',
        10: 'Jisas i tokim em, Em husat i waswas pinis i no gat nid long waswas, tupela fut bilong em tasol, tasol em i klin olgeta. Na yupela i stap klin, tasol i no yupela olgeta.',
        11: 'Long wanem, em i save long husat bai putim em long han bilong birua. Olsem na em i tok, I no yupela olgeta i klin.',
        12: 'Olsem tasol bihain long em i bin wasim ol fut bilong ol, na em i bin kisim ol klos bilong em, na sindaun gen, em i tokim ol, Yupela save long mi bin mekim wanem long yupela?',
        13: 'Yupela kolim mi Tisa na Bikpela. Na yupela i toktok gut. Long wanem, mi stap olsem.',
        14: 'Nau sapos mi, Bikpela na Tisa bilong yupela, i bin wasim ol fut bilong yupela, yupela tu i mas wasim ol fut bilong yupela wanpela i go long narapela.',
        15: 'Long wanem, mi bin givim yupela wanpela piksa, inap long yupela i ken mekim olsem mi bin mekim long yupela.',
        16: 'Tru tumas, tru tumas, mi tokim yupela, Wokboi i no winim bikman bilong em. Na tu em husat man i salim i no winim man husat i salim em.',
        17: 'Sapos yupela i save long ol dispela samting, amamas i stap long yupela sapos yupela i mekim ol.',
        18: '¶ Mi no toktok long sait bilong yupela olgeta. Mi save husat mi bin makim. Tasol inap long rait bilong God i ken kamap pinis, Em husat i kaikai bret wantaim mi i bin litimapim baksait bilong fut bilong em i birua long mi.',
        19: 'Nau mi tokim yupela bipo em i kamap, inap long, taim em i kamap olsem, yupela i ken save long mi stap dispela man.',
        20: 'Tru tumas, tru tumas, mi tokim yupela, Em husat i kisim husat man mi salim i kisim mi. Na em husat i kisim mi i kisim em husat i salim mi.',
        21: 'Taim Jisas i bin tok olsem, em i pilim wari long spirit sait, na tokaut klia, na tok, Tru tumas, tru tumas, mi tokim yupela, long wanpela bilong yupela bai putim mi long han bilong birua.',
        22: 'Nau ol disaipel i lukluk wanpela i go long narapela, na ol i gat tupela tingting long em i toktok long husat.',
        23: 'Nau i gat wanpela bilong ol disaipel bilong em i lindaun long bros bilong Jisas, husat Jisas i laikim tru.',
        24: 'Olsem na Saimon Pita i wokim mak wantaim han long em, inap long em i ken askim long i mas husat husat em i toktok long en',
        25: 'Nau em husat i slip long bros bilong Jisas i tokim em, Bikpela, em i husat?',
        26: 'Jisas i bekim tok, Em i dispela, long husat mi bai givim samting bilong putim long sup, taim mi bin putim dispela long sup. Na taim em i bin putim samting long sup, em i givim long Judas Iskariot, pikinini man bilong Saimon.',
        27: 'Na bihain long samting ol i putim long sup, Seten i go insait long em. Nau Jisas i tokim em, Dispela yu mekim, mekim kwiktaim.',
        28: 'Nau i no gat man long tebol i save long wanem as em i tokim dispela toktok long em.',
        29: 'Long wanem, sampela bilong ol i ting olsem, bikos Judas i bin holim bek, long Jisas i bin tokim em, Baim ol dispela samting long yumi gat nid long en long redi long taim bilong dispela bikpela kaikai. O, long em i mas givim samting long ol rabisman.',
        30: 'Nau taim em bin kisim samting ol i putim long sup em go ausait wantu. Na em i nait.',
        31: '¶ Olsem na, taim em i go ausait pinis, Jisas i tok, Nau Pikinini Man bilong man i kisim glori, na God i kisim glori insait long em.',
        32: 'Sapos God i kisim glori insait long em, God bai givim glori tu long em insait long em yet, na kwiktaim em bai givim glori long em.',
        33: 'Ol liklik pikinini, liklik taim yet mi stap wantaim yupela. Yupela bai painim mi. Na olsem mi tokim ol Ju pinis, We mi go, yupela i no inap kam. Olsem tasol nau mi tokim yupela.',
        34: 'Wanpela nupela tok strong mi givim long yupela, Long yupela i mas gat laikim tru wanpela i go long narapela. Olsem mi bin laikim tru yupela, long yupela tu i mas gat laikim tru wanpela i go long narapela.',
        35: 'Long dispela bai olgeta man i save long yupela i stap ol disaipel bilong mi, sapos yupela i gat laikim tru wanpela i go long narapela.',
        36: '¶ Saimon Pita i tokim em, Bikpela, yu go we? Jisas i bekim tok long em, We mi go, yu no inap bihainim mi nau. Tasol yu bai bihainim mi bihain long en.',
        37: 'Pita i tokim em, Bikpela, bilong wanem mi no inap bihainim yu nau? Mi bai givim laip bilong mi long tingim yu.',
        38: 'Jisas i bekim tok long em, Yu bai givim laip bilong yu long tingim mi? Tru tumas, tru tumas, mi tokim yu, Kakaruk man bai i no inap singaut, inap long yu bin tok nogat long mi tripela taim.',
    },
    14: {
        1: '¶ No ken larim bel bilong yupela pilim wari. Yupela i bilip long God, bilip tu long mi.',
        2: 'Long haus bilong Papa bilong mi planti bikpela naispela haus i stap. Sapos em i no olsem, mi bin tokim yupela. Mi go bilong redim wanpela ples bilong yupela.',
        3: 'Na sapos mi go na redim wanpela ples bilong yupela, mi bai kam bek gen, na kisim yupela i kam long mi yet, inap long we mi stap, long dispela hap yupela tu i ken stap.',
        4: '¶ Na we mi go yupela i save, na rot yupela i save.',
        5: 'Tomas i tokim em, Bikpela, mipela i no save long yu go we. Na mipela i ken save long rot olsem wanem?',
        6: 'Jisas i tokim em, Mi stap rot, tok tru, na laip. I no gat man bai kam long Papa long narapela rot, long mi tasol.',
        7: 'Sapos yupela i bin save long mi, yupela i mas bin save long Papa bilong mi tu. Na i stat long nau i go yupela i save long em, na yupela i bin lukim em.',
        8: 'Filip i tokim em, Bikpela, soim Papa long mipela, na em bai inap long mipela.',
        9: 'Jisas i tokim em, Ating mi bin stap longpela taim olsem wantaim yu, na yet yu no bin save long mi, Filip? Em husat i bin lukim mi i bin lukim Papa. Na olsem wanem yu tok nau, Soim Papa long mipela?',
        10: 'Ating i yes long yu bilip long mi stap insait long Papa, na Papa i stap insait long mi? Ol dispela toktok mi tokim yu mi no toktok long tingting bilong mi yet. Tasol Papa husat i stap insait long mi, em i mekim ol wok.',
        11: 'Bilipim mi long mi stap insait long Papa, na Papa i stap insait long mi. O sapos nogat, bilipim mi long tingim ol dispela wok stret.',
        12: '¶ Tru tumas, tru tumas, mi tokim yupela, Em husat i bilip long mi, ol dispela wok mi mekim bai em i mekim tu. Na ol wok i bikpela moa long ol dispela bai em i mekim. Bilong wanem, mi go long Papa bilong mi.',
        13: 'Na wanem samting yupela bai askim long nem bilong mi, dispela bai mi mekim, inap long Papa i ken kisim glori insait long Pikinini Man.',
        14: 'Sapos yupela bai askim wanpela samting long nem bilong mi, mi bai mekim dispela.',
        15: '¶ Sapos yupela i laikim mi tru, bihainim ol tok strong bilong mi.',
        16: 'Na mi bai beten long Papa, na em bai givim yupela narapela Poroman, inap long em i ken stap wantaim yupela oltaim oltaim.',
        17: 'Yes, Spirit bilong tok tru, husat dispela graun i no inap kisim, bilong wanem, em i no lukim em, o save long em. Tasol yupela i save long em. Long wanem, em i stap wantaim yupela, na em bai stap insait long yupela.',
        18: '¶ Mi bai i no inap lusim yupela taim yupela i no gat bel isi. Mi bai kam long yupela.',
        19: 'Liklik taim tasol, na ol manmeri bilong dispela graun i no inap lukim mi moa. Tasol yupela bai lukim mi. Bikos mi stap laip, yupela bai stap laip tu.',
        20: 'Long dispela de yupela bai save long mi stap insait long Papa bilong mi, na yupela insait long mi, na mi insait long yupela.',
        21: 'Em husat i gat ol tok strong bilong mi, na bihainim ol, em i dispela man husat i laikim mi tru. Na em husat i laikim mi tru bai Papa bilong mi i laikim tru, na mi bai laikim em tru, na mi bai soim mi yet ples klia long em.',
        22: 'Judas i tokim em, i no Iskariot, Bikpela, em bai olsem wanem long yu bai soim yu yet ples klia long mipela, na i no long ol manmeri bilong dispela graun?',
        23: 'Jisas i bekim na tokim em, Sapos wanpela man i laikim mi tru, em bai bihainim ol toktok bilong mi. Na Papa bilong mi bai laikim em tru, na Mitupela bai kam long em, na mekim ples bilong Mitupela bilong stap wantaim em.',
        24: 'Em husat i no laikim mi tru i no bihainim ol toktok bilong mi. Na dispela tok yupela i harim em i no bilong mi, tasol em i bilong Papa husat i salim mi.',
        25: '¶ Ol dispela samting mi bin toktok long yupela, taim mi stap yet long pes bilong yupela.',
        26: 'Tasol Poroman, husat em i Holi Spirit, husat Papa bai salim long nem bilong mi, em bai skulim yupela long olgeta samting, na bringim olgeta samting i kam bek long tingting bilong yupela, wanem samting mi bin tokim yupela.',
        27: 'Bel isi mi lusim wantaim yupela, bel isi bilong mi mi givim long yupela. Mi no givim yupela olsem dispela graun i givim. No ken larim bel bilong yupela pilim wari, na tu no ken larim em i ken pret.',
        28: '¶ Yupela i bin harim long mi tokim yupela olsem wanem, Mi go, na mi bai kam gen long yupela. Sapos yupela i laikim mi tru, yupela bai wokim amamas tru, bilong wanem, mi tok, Mi go long Papa. Long wanem, Papa bilong mi i winim mi.',
        29: 'Na nau mi bin tokim yupela bipo em i kamap olsem, inap long, taim em i kamap olsem, yupela i ken bilip.',
        30: 'Bihain long nau mi bai i no inap toktok planti wantaim yupela. Long wanem, hetman bilong dispela graun i kam, na em i no gat wanpela samting insait long mi.',
        31: 'Tasol inap long ol manmeri bilong dispela graun i ken save long mi laikim tru Papa, na olsem Papa i givim tok strong long mi, yes, olsem tasol mi mekim. Kirap, yumi go long hap.',
    },
    15: {
        1: '¶ Mi stap diwai wain tru, na Papa bilong mi em i man bilong lukautim gaden.',
        2: 'Olgeta wan wan han bilong diwai insait long mi husat i no karim kaikai em i tekewe. Na olgeta wan wan han bilong diwai husat i karim kaikai, em i klinim dispela, inap long em i ken karim moa kaikai.',
        3: 'Nau yupela i stap klin long dispela tok mi bin toktok long yupela.',
        4: 'Stap insait long mi, na mi insait long yupela. Olsem han bilong diwai i no inap karim kaikai long em yet, sapos em i no stap insait long diwai wain, yupela tu i no inap, sapos yupela i no stap insait long mi.',
        5: 'Mi stap dispela diwai wain, yupela i stap ol han bilong diwai. Em husat i stap insait long mi, na mi insait long em, em yet i karim planti kaikai. Long wanem, ausait long mi yupela i no inap wokim wanpela samting.',
        6: 'Sapos wanpela man i no stap insait long mi, Papa bai tromoi em i go ausait olsem wanpela han bilong diwai, na em i drai. Na ol man i bungim ol, na tromoi ol i go insait long paia, na ol i kuk.',
        7: 'Sapos yupela i stap insait long mi, na ol toktok bilong mi i stap insait long yupela, yupela bai askim wanem samting yupela i laik, na em bai kamap long yupela.',
        8: 'Papa bilong mi i kisim glori insait long dispela, long yupela i karim planti kaikai. Olsem tasol yupela bai stap ol disaipel bilong mi.',
        9: '¶ Olsem Papa i bin laikim mi tru, olsem tasol mi bin laikim yupela tru. Yupela i mas stap yet insait long laikim tru bilong mi.',
        10: 'Sapos yupela i bihainim ol tok strong bilong mi, yupela bai stap insait long laikim tru bilong mi. Yes, olsem mi bin bihainim ol tok strong bilong Papa bilong mi, na stap yet insait long laikim tru bilong em.',
        11: 'Ol dispela samting mi bin toktok long yupela, inap long amamas tru bilong mi i ken stap yet insait long yupela, na long amamas tru bilong yupela i ken pulap.',
        12: 'Dispela em i tok strong bilong mi, Long yupela i gat laikim tru wanpela i go long narapela, olsem mi bin laikim yupela tru.',
        13: 'I no gat narapela laikim tru i winim dispela, long wanpela man i givim laip bilong em bilong helpim ol pren bilong em.',
        14: 'Yupela i stap ol pren bilong mi, sapos yupela i mekim wanem samting mi tok strong long yupela.',
        15: 'I stat long nau i go mi no kolim yupela ol wokboi. Long wanem, wokboi i no save long bikman bilong em i mekim wanem. Tasol mi bin kolim yupela ol pren. Long wanem, olgeta dispela samting mi bin harim long Papa bilong mi mi bin mekim yupela long save.',
        16: 'Yupela i no bin makim mi, tasol mi bin makim yupela, na makim yupela long wok, inap long yupela i ken go na karim kaikai, na long kaikai bilong yupela i ken stap yet. Inap long wanem samting yupela bai askim long Papa long nem bilong mi, em i ken givim dispela long yupela.',
        17: 'Ol dispela samting mi tok strong long yupela, inap long yupela i ken gat laikim tru wanpela i go long narapela.',
        18: '¶ Sapos dispela graun i hetim yupela, yupela i save long em i hetim mi bipo long em i hetim yupela.',
        19: 'Sapos yupela i bilong dispela graun, dispela graun bai laikim tru ol bilong em yet. Tasol bikos yupela i no bilong dispela graun, tasol mi bin makim yupela ausait long dispela graun, olsem na dispela graun i hetim yupela.',
        20: 'Tingim gen long dispela tok mi tokim yupela, Wokboi i no winim bikman bilong em. Sapos ol i bin givim hevi long mi, ol bai givim hevi long yupela tu. Sapos ol i bin bihainim tok bilong mi, ol bai bihainim tok bilong yupela tu.',
        21: 'Tasol olgeta dispela samting bai ol i mekim long yupela bilong tingim nem bilong mi, bilong wanem, ol i no save em husat i salim mi.',
        22: 'Sapos mi no bin kam na toktok long ol, ol i no bin gat sin. Tasol nau ol i no gat ausait saket bilong haitim sin bilong ol.',
        23: 'Em husat i hetim mi i hetim Papa bilong mi tu.',
        24: 'Sapos mi no bin mekim namel long ol ol dispela wok i no gat wanpela arapela man i mekim, ol i no bin gat sin. Tasol nau ol i bin lukim na ol i hetim mi na Papa bilong mi wantaim.',
        25: 'Tasol dispela i kamap olsem, inap long dispela tok ol i raitim long lo bilong ol i ken kamap pinis, Ol i hetim mi taim i no gat as bilong en.',
        26: '¶ Tasol taim Poroman i kam pinis, husat mi bai salim long yupela i kam long Papa, yes, Spirit bilong tok tru, husat i kam ausait long Papa, em bai tokaut klia long mi.',
        27: 'Na yupela tu bai stap witnes, bilong wanem, yupela i bin stap wantaim mi long stat i kam inap long nau.',
    },
    16: {
        1: '¶ Ol dispela samting mi bin toktok long yupela, inap long bel bilong yupela i no ken bagarap.',
        2: 'Ol bai putim yupela ausait long ol sinagog. Yes, taim bai kam, long husat man i kilim yupela bai ting long em i wokim wok bilong God.',
        3: 'Na ol dispela samting bai ol i mekim long yupela, bilong wanem, ol i no bin save long Papa, o mi.',
        4: 'Tasol ol dispela samting mi bin tokim yupela, long taim dispela taim bai kam, yupela i ken holim tingting long mi tokim yupela pinis long ol. Na ol dispela samting mi no tokim yupela long stat, bilong wanem, mi stap wantaim yupela.',
        5: 'Tasol nau mi go long rot bilong mi long em husat i salim mi. Na i no gat wanpela bilong yupela i askim mi, Yu go we?',
        6: 'Tasol bikos mi bin tokim ol dispela samting long yupela, bel hevi i bin pulimapim bel bilong yupela.',
        7: '¶ Tasol mi tok tru long yupela. Em i gutpela bilong helpim yupela long mi go. Long wanem, sapos mi no go, Poroman bai i no inap kam long yupela. Tasol sapos mi go, mi bai salim em long yupela.',
        8: 'Na taim em i kam pinis, em bai krosim ol manmeri bilong dispela graun long sin, na long stretpela pasin, na long kot.',
        9: 'Long sin, bilong wanem, ol i no bilip long mi.',
        10: 'Long stretpela pasin, bilong wanem, mi go long Papa, na yupela i no lukim mi moa.',
        11: 'Long kot, bilong wanem, God i jasim hetman bilong dispela graun.',
        12: 'Mi gat planti samting yet long tokim yupela, tasol yupela i no inap long karim ol nau.',
        13: 'Tasol taim em, Spirit bilong tok tru, i kam, em bai stiaim yupela long olgeta tok tru. Long wanem, em bai i no inap toktok long em yet. Tasol wanem samting em bai harim, dispela bai em i toktok. Na em bai soim yupela ol samting bilong kamap bihain.',
        14: 'Em bai givim glori long mi. Long wanem, em bai kisim samting bilong mi, na em bai soim dispela long yupela.',
        15: 'Olgeta dispela samting Papa i gat em i bilong mi. Olsem na mi tok, long em bai kisim samting bilong mi, na em bai soim dispela long yupela.',
        16: '¶ Liklik taim yet, na yupela bai i no inap lukim mi. Na gen, liklik taim yet, na yupela bai lukim mi, bilong wanem, mi go long Papa.',
        17: 'Nau sampela bilong ol disaipel bilong em i toktok namel long ol yet, Dispela em i tokim yumi em wanem, Liklik taim yet, na yupela bai i no inap lukim mi, na gen, liklik taim yet, na yupela bai lukim mi, na, Bilong wanem, mi go long Papa?',
        18: 'Olsem na ol i tok, Dispela em i tokim yumi em wanem, Liklik taim yet? Yumi i no inap long save long em i tok wanem.',
        19: 'Nau Jisas i save long ol i gat laik long askim em, na em i tokim ol, Ating yupela i askim namel long yupela yet long dispela mi tok, Liklik taim yet, na yupela bai i no inap lukim mi, na gen, liklik taim yet, na yupela bai lukim mi?',
        20: 'Tru tumas, tru tumas, mi tokim yupela, Long yupela bai krai tru na krai sori, tasol ol manmeri bilong dispela graun bai wokim amamas tru. Na bel bilong yupela bai pilim hevi, tasol bel hevi bilong yupela bai tanim i kamap amamas tru.',
        21: 'Taim meri i hatwok wantaim pen em i gat bel hevi, bilong wanem, aua bilong em i kamap. Tasol long taim stret long em i karim pikinini, em i no tingim gen moa taim hevi i krungutim em, long wanem, em i amamas tru long em i karim wanpela man i kam long dispela graun.',
        22: 'Na olsem na nau yupela i gat bel hevi. Tasol mi bai lukim yupela gen, na bel bilong yupela bai wokim amamas tru, na i no gat man bai tekewe amamas tru bilong yupela long yupela.',
        23: '¶ Na long dispela de yupela bai i no inap askim mi long wanpela samting. Tru tumas, tru tumas, mi tokim yupela, Wanem samting yupela bai askim long Papa long nem bilong mi, em bai givim dispela long yupela.',
        24: 'Inap long nau yupela i no bin askim wanpela samting long nem bilong mi. Askim, na yupela bai kisim, inap long amamas tru bilong yupela i ken pulap.',
        25: 'Ol dispela samting mi bin toktok long yupela long ol provep. Tasol taim bai kamap, taim mi bai i no inap toktok moa long yupela long ol provep, tasol mi bai soim yupela klia planti samting long sait bilong Papa.',
        26: 'Long dispela de yupela bai askim long nem bilong mi. Na mi no tokim yupela, long mi bai beten long Papa long sait bilong yupela.',
        27: 'Long wanem, Papa em yet i laikim yupela tru, bilong wanem, yupela i bin laikim mi tru, na yupela i bin bilip long mi lusim God i kam ausait.',
        28: '¶ Mi lusim Papa i kam ausait, na mi kam long dispela graun. Na gen, mi lusim dispela graun, na go long Papa.',
        29: 'Ol disaipel bilong em i tokim em, Harim, nau yu toktok klia, na yu no toktok long wanpela provep.',
        30: 'Nau mipela i save tru long yu save long olgeta samting, na yu no gat nid long wanpela man i mas askim yu. Long dispela mipela i bilip long yu lusim God i kam ausait.',
        31: 'Jisas i bekim tok long ol, Nau yupela i bilip?',
        32: 'Lukim, aua bai kam, yes, em i kam nau, long yupela bai bruk nabaut, olgeta wan wan man long em yet, na bai lusim mi i stap wanpis. Na yet mi no stap wanpis, bilong wanem, Papa i stap wantaim mi.',
        33: 'Ol dispela samting mi bin toktok long yupela, inap long insait long mi yupela i ken gat bel isi. Long dispela graun yupela bai gat bikpela hevi. Tasol stap wantaim gutpela amamas. Mi bin winim dispela graun.',
    },
    17: {
        1: '¶ Ol dispela toktok Jisas i tok, na litimapim tupela ai bilong em i go long heven, na tok, Papa, dispela aua i kam pinis. Givim glori long Pikinini Man bilong yu, inap long Pikinini Man bilong yu tu i ken givim glori long yu.',
        2: 'Olsem yu bin givim em pawa long bosim olgeta bodi, inap long em i ken givim laip i stap gut oltaim oltaim long hamas man yu bin givim em.',
        3: 'Na dispela em i laip i stap gut oltaim oltaim, long ol i ken save long yu, dispela wanpela God tru tasol, na Jisas Kraist, husat yu bin salim.',
        4: 'Mi bin givim glori long yu long dispela graun. Mi bin pinisim dispela wok yu givim mi long mekim.',
        5: 'Na nau, O Papa, yu givim glori long mi wantaim yu yet wantaim dispela glori mi bin gat wantaim yu bipo long dispela graun i stap.',
        6: '¶ Mi bin mekim nem bilong yu i kamap ples klia long ol man husat yu givim mi ausait long dispela graun. Ol i bilong yu, na yu givim ol long mi. Na ol i bin holimpas tok bilong yu.',
        7: 'Nau ol i bin save long olgeta wanem samting yu bin givim long mi i kam long yu.',
        8: 'Long wanem, mi bin givim long ol ol dispela toktok yu givim mi. Na ol i bin kisim ol, na ol i bin save tru tumas long mi kam ausait long yu, na ol i bin bilip long yu bin salim mi.',
        9: 'Mi beten long ol. Mi no beten long ol manmeri bilong dispela graun, tasol long ol husat yu bin givim mi. Long wanem, ol i bilong yu.',
        10: 'Na olgeta bilong mi i bilong yu, na bilong yu i bilong mi. Na mi kisim glori long ol.',
        11: '¶ Na nau mi no stap moa long dispela graun, tasol ol dispela i stap long dispela graun, na mi kam long yu. Holi Papa, holimpas, long nem bilong yu yet, ol dispela husat yu bin givim mi, inap long ol i ken stap wanpela, olsem yumi stap.',
        12: 'Taim mi stap wantaim ol long dispela graun, mi lukautim ol long nem bilong yu. Ol dispela husat yu givim long mi mi bin lukautim, na i no gat wanpela bilong ol i lus, pikinini man bilong bagarap olgeta long hel tasol, inap long rait bilong God i ken kamap pinis.',
        13: 'Na nau mi kam long yu. Na ol dispela samting mi toktok taim mi stap long dispela graun, inap long ol i ken gat amamas tru bilong mi i kamap pinis insait long ol yet.',
        14: 'Mi bin givim tok bilong yu long ol. Na ol manmeri bilong dispela graun i bin hetim ol, bilong wanem, ol i no bilong dispela graun, yes, olsem mi no bilong dispela graun.',
        15: 'Mi no beten long yu mas tekewe ol ausait long dispela graun, tasol long yu mas pasim ol long pasin nogut.',
        16: 'Ol i no bilong dispela graun, yes, olsem mi no bilong dispela graun.',
        17: '¶ Mekim ol i kamap holi long tok tru bilong yu. Tok bilong yu i tru.',
        18: 'Olsem yu bin salim mi long dispela graun, yes, olsem tasol mi tu i bin salim ol long dispela graun.',
        19: 'Na bilong tingim ol mi mekim mi yet long kamap holi, inap long ol tu i ken kamap holi long tok tru.',
        20: '¶ Na tu mi no beten long ol dispela tasol, tasol long ol tu husat bai bilip long mi long tok bilong ol,',
        21: 'Inap long ol olgeta i ken stap wanpela. Olsem yu, Papa, i stap insait long mi, na mi insait long yu, long ol tu i ken stap wanpela insait long yumi. Inap long ol man bilong dispela graun i ken bilip long yu bin salim mi.',
        22: 'Na dispela glori yu givim mi mi bin givim ol. Inap long ol i ken stap wanpela, yes, olsem yumi stap wanpela.',
        23: 'Mi insait long ol, na yu insait long mi, inap long ol i ken kamap inap tru insait long wanpela, na inap long ol manmeri bilong dispela graun i ken save long yu bin salim mi, na yu bin laikim ol tru, olsem yu bin laikim mi tru.',
        24: '¶ Papa, mi gat laik long ol tu, husat yu bin givim mi, i ken stap wantaim mi we mi stap, inap long ol i ken lukim glori bilong mi, dispela yu bin givim mi. Long wanem, yu laikim mi tru bipo yu slipim ol as ston bilong dispela graun.',
        25: 'O stretpela Papa, ol man bilong dispela graun i no bin save long yu. Tasol mi bin save long yu, na ol dispela i bin save long yu bin salim mi.',
        26: 'Na mi bin tokaut long ol long nem bilong yu, na mi bai tokaut long en, inap long dispela laikim tru we yu bin laikim mi tru long en i ken stap insait long ol, na mi insait long ol.',
    },
    18: {
        1: '¶ Taim Jisas i bin toktok long ol dispela toktok, em i go ausait wantaim ol disaipel bilong em hapsait long liklik wara Kidron, we wanpela gaden i stap, na em i go insait long dispela, na ol disaipel bilong em.',
        2: 'Na Judas tu, husat i putim em long han bilong birua, i save long dispela ples. Long wanem, planti taim Jisas i go long dispela hap wantaim ol disaipel bilong em.',
        3: 'Nau Judas, taim em i kisim wanpela liklik lain ami bilong ol man na ol ofisa long ol bikpris na ol Farisi, i kam long dispela hap wantaim ol lam na ol bombom na ol samting bilong pait.',
        4: 'Olsem na Jisas, taim em i save olgeta dispela samting i bai kamap long em, i go ausait, na tokim ol, Yupela i painim husat?',
        5: 'Ol i bekim tok long em, Jisas bilong Nasaret. Jisas i tokim ol, Mi stap dispela man. Na Judas tu, husat i putim em long han bilong birua, i sanap wantaim ol.',
        6: 'Nau long taim stret long em i bin tokim ol, Mi stap dispela man, ol i go bek, na pundaun long graun.',
        7: 'Nau em i askim ol gen, Yupela i painim husat? Na ol i tok, Jisas bilong Nasaret.',
        8: 'Jisas i bekim tok long ol, Mi bin tokim yupela pinis long mi stap dispela man. Olsem na sapos yupela i painim mi, larim ol dispela i go long rot bilong ol,',
        9: 'Inap long dispela toktok i ken kamap pinis, dispela em i tok, Bilong ol husat yu givim mi mi no bin lusim wanpela.',
        10: 'Nau taim Saimon Pita i gat wanpela bainat em i pulim dispela, na paitim wokboi bilong hetpris, na katim i go han sut sait ia bilong em. Nem bilong dispela wokboi em Malkas.',
        11: 'Nau Jisas i tokim Pita, Putim bainat bilong yu i go long paus. Dispela kap Papa bilong mi i bin givim mi, ating i yes long mi bai dringim dispela?',
        12: 'Nau liklik lain soldia na kepten na ol ofisa bilong ol Ju i kisim Jisas, na pasim em wantaim baklain samting,',
        13: '¶ Na stiaim em i go long Anas pastaim. Long wanem, em i tambu papa bilong Kaiafas, husat i hetpris dispela yia stret.',
        14: 'Nau Kaiafas em i dispela, husat i givim tok helpim long ol Ju, long em i gutpela bilong helpim long wanpela man i ken dai bilong helpim ol manmeri.',
        15: 'Na Saimon Pita i bihainim Jisas, na narapela disaipel i mekim olsem. Hetpris i save long dispela disaipel, na em i go insait wantaim Jisas long haus king bilong hetpris.',
        16: 'Tasol Pita i sanap long dua ausait. Nau dispela arapela disaipel i go ausait, husat hetpris i save long em, na toktok wantaim meri husat i lukautim dua, na em i bringim Pita insait.',
        17: 'Nau dispela yangpela meri husat i lukautim dua i tokim Pita, Ating i yes long yu tu i wanpela bilong ol disaipel bilong dispela man? Em i tok, Mi nogat.',
        18: 'Na ol wokboi na ol ofisa i sanap long dispela hap, husat i bin wokim wanpela paia long ol sakol, long wanem, em i kol. Na ol i hatim skin bilong ol yet. Na Pita i sanap wantaim ol, na hatim skin bilong em yet.',
        19: 'Nau hetpris i askim Jisas long ol disaipel bilong em, na long skul bilong em.',
        20: 'Jisas i bekim tok long em, Mi toktok ples klia long dispela graun. Oltaim mi givim skul long sinagog, na long tempel, we ol Ju i go olgeta taim. Na mi no bin tokim wanpela samting hait.',
        21: 'Bilong wanem yu askim mi? Askim ol husat i harim mi pinis long wanem samting mi bin tokim ol. Lukim, ol i save mi tok wanem.',
        22: 'Na taim em i bin toktok olsem, wanpela bilong ol ofisa husat i sanap klostu i paitim Jisas wantaim pes bilong han bilong em, i spik, Yu bekim tok long hetpris olsem?',
        23: 'Jisas i bekim tok long em, Sapos mi bin mekim toktok i nogut, stap witnes bilong dispela nogut. Tasol sapos gutpela, bilong wanem yu paitim mi?',
        24: 'Nau Anas i bin salim em, pas wantaim baklain, i go long hetpris Kaiafas.',
        25: 'Na Saimon Pita i sanap na hatim skin bilong em yet. Olsem na ol i tokim em, Ating i yes long yu tu i wanpela bilong ol disaipel bilong em? Em i tok nogat long en, na tok, Mi nogat.',
        26: 'Wanpela bilong ol wokboi bilong hetpris, husat i kandre bilong em husat Pita i bin katim ia bilong em i go, i tok, Ating i yes long mi lukim yu long gaden wantaim em?',
        27: 'Pita nau i tok nogat gen, na wantu tasol kakaruk man i singaut.',
        28: '¶ Nau ol i stiaim Jisas i go lusim Kaiafas i go long haus kot. Na em i moning tru. Na ol ol yet i no go insait long haus kot, nogut ol i ken kamap doti, tasol inap long ol i ken kaikai long pasova.',
        29: 'Nau Pailat i go ausait long ol, na tok, Yupela i sutim wanem tok i birua long dispela man?',
        30: 'Ol i bekim na tokim em, Sapos em i no wanpela raskol, mipela i no bin givim em i go long yu.',
        31: 'Nau Pailat i tokim ol, Yupela kisim em, na jasim em bilong bihainim lo bilong yupela. Olsem na ol Ju i tokim em, Em i tambu long lo long mipela i ken mekim wanpela man i dai,',
        32: 'Inap long dispela toktok bilong Jisas i ken kamap pinis, dispela em i toktok bilong mekim klia wanem dai em i mas dai long en.',
        33: 'Nau Pailat i go insait long haus kot gen, na singautim Jisas, na tokim em, Yu King bilong ol Ju?',
        34: 'Jisas i bekim tok long em, Yu toktok long dispela samting long yu yet, o ol arapela i bin tokim yu dispela long sait bilong mi?',
        35: 'Pailat i bekim tok, Mi wanpela Ju? Kantri bilong yu yet na ol bikpris i bin givim yu long mi. Yu bin mekim wanem?',
        36: 'Jisas i bekim tok, Kingdom bilong mi i no bilong dispela graun. Sapos kingdom bilong mi i bilong dispela graun, orait ol wokboi bilong mi bai pait, inap long ol man i no inap givim mi long ol Ju. Tasol nau kingdom bilong mi i no kam long hia.',
        37: 'Olsem na Pailat i tokim em, Yu stap wanpela king nau? Jisas i bekim tok, Yu tok long mi wanpela king. Long kamap long dispela mak mama i karim mi, na long dispela as mi kam long dispela graun, inap long mi ken stap witnes long tok tru. Olgeta wan wan husat i bilong tok tru i harim nek bilong mi.',
        38: 'Pailat i tokim em, Tok tru em i wanem samting? Na taim em bin mekim dispela tok, em i go ausait gen long ol Ju, na tokim ol, Mi no lukim wanpela asua long em liklik.',
        39: 'Tasol yupela i gat wanpela kastam, long mi mas lusim wanpela i go long yupela long pasova. Olsem na yupela i gat laik long mi ken lusim King bilong ol Ju i go long yupela?',
        40: 'Nau olgeta i singaut gen, i spik, I no dispela man, tasol Barabas. Nau Barabas em i wanpela raskol stilman.',
    },
    19: {
        1: '¶ Olsem na nau Pailat i kisim Jisas, na wipim em.',
        2: 'Na ol soldia i wokim wanpela hat king bilong ol rop i gat nil, na putim dispela antap long het bilong em, na ol i putim wanpela purpelpela longpela saket long em,',
        3: 'Na ol i tok, Gude, King bilong ol Ju! Na ol i paitim em wantaim ol han bilong ol.',
        4: 'Olsem na Pailat i go ausait gen, na tokim ol, Lukim, mi bringim em i kam ausait long yupela, inap long yupela i ken save long mi no painim asua long em.',
        5: 'Nau Jisas i kam ausait, taim em i werim hat king bilong ol rop i gat nil, na purpelpela longpela saket. Na Pailat i tokim ol, Lukim dispela man!',
        6: 'Olsem na taim ol bikpris na ol ofisa i lukim em, ol i singaut, i spik, Nilim em long diwai kros, nilim em long diwai kros. Pailat i tokim ol, Yupela kisim em, na nilim em long diwai kros. Long wanem, mi no lukim asua long em.',
        7: 'Ol Ju i bekim tok long em, Mipela i gat wanpela lo, na long lo bilong mipela em i mas dai, bilong wanem, em i mekim em yet Pikinini Man bilong God.',
        8: 'Olsem na taim Pailat i harim dispela tok, em i pret moa.',
        9: 'Na em i go gen insait long haus kot, na tokim Jisas, Yu kam long we? Tasol Jisas i no bekim tok long em.',
        10: 'Nau Pailat i tokim em, Yu no toktok long mi? Ating i yes long yu save long mi gat pawa long nilim yu long diwai kros, na mi gat pawa long lusim yu i go?',
        11: 'Jisas i bekim tok, Yu no ken gat pawa liklik i birua long mi, sapos wanpela i no givim dispela long yu long antap. Olsem na em husat i givim mi long yu i gat sin i bikpela moa.',
        12: 'Na i stat long dispela taim i go Pailat i painim rot long lusim em i go. Tasol ol Ju i singaut, i spik, Sapos yu lusim dispela man i go, yu no stap pren bilong Sisa. Husat man i mekim em yet wanpela king i mekim toktok i birua long Sisa.',
        13: 'Olsem na taim Pailat i harim dispela tok, em i bringim Jisas ausait, na sindaun long sia kot long dispela ples ol i kolim Plua Ston, tasol long tok ples Hibru, Gabata.',
        14: 'Na em i de bilong redim pasova, na klostu olsem long namba sikis aua. Na em i tokim ol Ju, Lukim King bilong yupela!',
        15: 'Tasol ol i singaut, Rausim em, rausim em, nilim em long diwai kros. Pailat i tokim ol, Bai mi nilim King bilong yupela long diwai kros? Na ol bikpris i bekim tok, Mipela i no gat narapela king, Sisa tasol.',
        16: '¶ Olsem na nau em i givim em long ol long nilim em long diwai kros. Na ol i kisim Jisas, na bringim em i go.',
        17: 'Na em i karim diwai kros bilong em i go ausait i go insait long ples ol i kolim ples bilong bun bilong het, dispela ol i kolim long tok ples Hibru Golgata,',
        18: 'We ol i nilim em long diwai kros, na tupela arapela wantaim em, wanpela long narapela narapela sait, na Jisas namel.',
        19: '¶ Na Pailat i raitim wanpela het tok, na putim dispela antap long diwai kros. Na dispela rait em, JISAS BILONG NASARET KING BILONG OL JU.',
        20: 'Nau planti bilong ol Ju i ritim dispela het tok. Long wanem, ples we ol i nilim Jisas long diwai kros em i klostu long biktaun. Na em i raitim dispela long Hibru, na Grik, na Latin.',
        21: 'Nau ol bikpris bilong ol Ju i tokim Pailat, No ken raitim, King bilong ol Ju, tasol long em i tok, Mi King bilong ol Ju.',
        22: 'Pailat i bekim tok, Wanem samting mi bin raitim mi bin raitim.',
        23: 'Nau ol soldia, taim ol i bin nilim Jisas long diwai kros, i kisim ol klos bilong em, na wokim fopela hap, long olgeta wan wan soldia wanpela hap. Na tu saket bilong em. Nau saket bilong em i no gat samap, ol i wokim dispela i stat long antap i go long olgeta hap bilong en.',
        24: 'Olsem na ol i toktok namel long ol yet, No ken larim yumi brukim dispela, tasol yumi mas tromoi satu long en, long em bai bilong husat, inap long rait bilong God i ken kamap pinis, dispela i tok, Ol i brukim ol klos bilong mi namel long ol, na long naispela klos bilong mi ol i bin tromoi satu. Olsem na ol dispela samting ol soldia i mekim.',
        25: 'Nau mama bilong Jisas i sanap klostu long diwai kros, na susa bilong mama bilong em, Maria, meri bilong Kliopas, na Maria Makdalin.',
        26: 'Olsem na taim Jisas i lukim mama bilong em, na disaipel i sanap klostu long em, husat em i laikim tru, em i tokim mama bilong em, Meri, lukim pikinini man bilong yu!',
        27: 'Nau em i tokim dispela disaipel, Lukim mama bilong yu! Na long dispela aua dispela disaipel i kisim em i go long haus bilong em yet.',
        28: 'Bihain long dispela, taim Jisas i save long nau olgeta samting i kamap pinis, inap long rait bilong God i ken kamap pinis, em i tok, Mi nekdrai.',
        29: 'Nau i gat wanpela sospen samting ol i putim i pulap long vinega. Na ol i pulapim wanpela spans wantaim vinega, na putim dispela antap long hisop, na putim dispela klostu long maus bilong em.',
        30: 'Olsem na taim Jisas i bin kisim vinega, em i tok, Em i pinis. Na em i lindaunim het bilong em, na lusim spirit bilong em.',
        31: '¶ Olsem na ol Ju, bikos em i de bilong redim pasova, inap long ol bodi i no ken stap yet antap long diwai kros long de sabat, (long wanem, dispela de sabat em i wanpela de antap,) i askim Pailat plis strong long ol i ken brukim ol lek bilong ol, na long ol i ken rausim ol i go.',
        32: 'Nau ol soldia i kam, na brukim tupela lek bilong namba wan, na bilong arapela husat ol i nilim long diwai kros wantaim em.',
        33: 'Tasol taim ol i kam long Jisas, na luksave long em i dai pinis, ol i no brukim tupela lek bilong em.',
        34: 'Tasol wanpela bilong ol soldia i sutim sait bilong em wantaim wanpela spia bilong tromoi, na wantu blut na wara i kam ausait.',
        35: 'Na em husat i lukim dispela i stap witnes, na witnes bilong em i tru. Na em i save long em i tok tru, inap long yupela i ken bilip.',
        36: 'Long wanem, ol i mekim ol dispela samting, inap long rait bilong God i ken kamap pinis, Wanpela bun bilong em bai i no inap bruk.',
        37: 'Na gen narapela rait bilong God i tok, Ol bai lukluk long em husat ol i sutim.',
        38: '¶ Na bihain long dispela, Josep bilong Arimatia, husat i wanpela disaipel bilong Jisas, tasol hait, long wanem, em i pret long ol Ju, i askim Pailat plis strong long em i ken kisim bodi bilong Jisas i go. Na Pailat i oraitim em. Olsem na em i kam, na kisim bodi bilong Jisas.',
        39: 'Na Nikodimas i kam tu, husat pastaim i kam long Jisas long nait, na em i bringim mur ol i bin abusim wantaim ol alo, i hevi klostu olsem 100 paun.',
        40: 'Nau ol i kisim bodi bilong Jisas, na raunim dispela insait long klos bilong naispela laplap wantaim ol spais, olsem em i kastam bilong ol Ju long planim.',
        41: 'Nau long ples we ol i nilim em long diwai kros i gat wanpela gaden. Na long dispela gaden wanpela nupela matmat i stap, we ol i no bin slipim wanpela man yet insait long en.',
        42: 'Olsem na long dispela hap ol i slipim Jisas, bilong wanem, em i de bilong ol Ju bilong redim, long wanem, dispela matmat i stap klostu tru.',
    },
    20: {
        1: '¶ Long namba wan de bilong wik, Maria Makdalin i kam long moning tru, taim em i tudak yet, i kam long matmat, na luksave olsem ol i bin rausim dispela ston long matmat.',
        2: 'Nau em i ran, na kam long Saimon Pita, na long dispela arapela disaipel, husat Jisas i laikim tru, na tokim ol, Ol i bin kisim Bikpela i go ausait long matmat, na mipela i no save ol i bin slipim em we.',
        3: 'Olsem na Pita i go ausait, na dispela arapela disaipel, na kam long matmat.',
        4: 'Olsem tasol ol i ran tupela wantaim. Na dispela arapela disaipel i bin winim Pita long ran, na kamap pastaim long matmat.',
        5: 'Na taim em i lindaun, na taim em i lukluk insait, em i lukim ol klos bilong naispela laplap i slip. Tasol em i no go insait.',
        6: 'Nau Saimon Pita i kam bihainim em, na go insait long matmat, na lukim ol klos bilong naispela laplap i slip,',
        7: 'Na liklik laplap, dispela i bin stap nabaut long het bilong em, i no slip wantaim ol klos bilong naispela laplap, tasol i pas wantaim long wanpela ples em yet.',
        8: 'Nau dispela arapela disaipel i go insait tu, husat i kam long matmat pastaim, na em i lukim, na bilipim.',
        9: 'Long wanem, inap long nau ol i no save long dispela rait bilong God, long em i mas kirap bek gen long dai.',
        10: 'Nau ol disaipel i go gen long haus bilong ol yet.',
        11: '¶ Tasol Maria i sanap ausait long matmat na krai tru. Na taim em i krai tru, em i lindaun, na lukluk insait long matmat,',
        12: 'Na lukim tupela ensel long waitpela klos i sindaun, wanpela long het, na arapela long ol fut, we bodi bilong Jisas i bin slip.',
        13: 'Na ol i tokim em, Meri, bilong wanem yu krai tru? Em i tokim ol, Bilong wanem, ol i bin kisim Bikpela bilong mi i go, na mi no save ol i bin slipim em we.',
        14: 'Na taim em i bin tok olsem, em i tanim em yet bek, na lukim Jisas i sanap, na em i no save long dispela em i Jisas.',
        15: 'Jisas i tokim em, Meri, bilong wanem yu krai tru? Yu painim husat? Meri, taim em i ting olsem em i man bilong lukautim gaden, i tokim em, Bikman, sapos yu bin karim em long hia, tokim mi long yu bin slipim em we, na mi bai kisim em i go.',
        16: 'Jisas i tokim em, Maria. Em i tanim em yet, na tokim em, Rabonai. Dispela tok em, Tisa.',
        17: 'Jisas i tokim em, No ken tasim mi. Long wanem, mi no go antap yet long Papa bilong mi. Tasol go long ol brata bilong mi, na tokim ol, mi go antap i go long Papa bilong mi, na Papa bilong yupela, na long God bilong mi, na God bilong yupela.',
        18: 'Maria Makdalin i kam na tokim ol disaipel long em i bin lukim Bikpela, na long em i bin toktok long em long ol dispela samting.',
        19: '¶ Nau long dispela de stret long apinun tru, taim em i namba wan de bilong wik, taim ol dua i pas we ol disaipel i bung, long wanem, ol i pret long ol Ju, Jisas i kam na sanap namel long ol, na tokim ol, Bel isi i stap long yupela.',
        20: 'Na taim em i bin tok olsem, em i soim ol tupela han bilong em na sait bilong em. Nau ol disaipel i amamas, taim ol i lukim Bikpela.',
        21: 'Nau Jisas i tokim ol gen, Bel isi i stap long yupela. Olsem Papa bilong mi i bin salim mi, yes, olsem tasol mi salim yupela.',
        22: 'Na taim em i bin tokim dispela, em i winim win antap long ol, na tokim ol, Yupela kisim Holi Spirit.',
        23: 'Ol sin bilong husat man yupela i lusim, ol i lus pinis long ol. Na ol sin bilong husat man yupela i holim yet, ol i stap yet.',
        24: 'Tasol Tomas, wanpela bilong dispela twelpela, husat ol i kolim Didimas, i no stap wantaim ol taim Jisas i kam.',
        25: 'Olsem na ol arapela disaipel i tokim em, Mipela i bin lukim Bikpela. Tasol em i tokim ol, Sapos mi no lukim mak bilong ol nil long tupela han bilong em, na putim pinga bilong mi insait long mak bilong ol nil, na sutim han bilong mi insait long sait bilong em, mi no inap bilipim.',
        26: '¶ Na bihain long etpela de gen ol disaipel bilong em i stap insait, na Tomas wantaim ol. Nau Jisas i kam, taim ol dua i pas, na sanap namel long ol, na tok, Bel isi i stap long yupela.',
        27: 'Nau em i tokim Tomas, Putim pinga bilong yu i kam long hia, na lukim tupela han bilong mi. Na putim han bilong yu long hia, na sutim dispela insait long sait bilong mi. Na no ken stap man i no gat bilip, tasol man i bilip.',
        28: 'Na Tomas i bekim na tokim em, Bikpela bilong mi, na God bilong mi.',
        29: 'Jisas i tokim em, Tomas, bikos yu bin lukim mi, yu bin bilip. Blesing i stap long ol husat i no bin lukim, na yet ol i bin bilipim.',
        30: 'Na planti arapela mak, tru tumas, Jisas i wokim long pes bilong ol disaipel bilong em, dispela mi no raitim long dispela buk.',
        31: 'Tasol ol dispela samting mi raitim, inap long yupela i ken bilip long Jisas em i Kraist, Pikinini Man bilong God. Na long taim yupela i bilip yupela i ken gat laip long nem bilong em.',
    },
    21: {
        1: '¶ Bihain long ol dispela samting Jisas i soim em yet gen long ol disaipel long biksi Taibirias. Na long dispela pasin em i soim em yet.',
        2: 'I gat i stap wantaim, Saimon Pita, na Tomas husat ol i kolim Didimas, na Nataniel bilong Kena insait long Galili, na ol pikinini man bilong Sebedi, na tupela arapela bilong ol disaipel bilong em.',
        3: 'Saimon Pita i tokim ol, Mi go bilong painim pis. Ol i tokim em, Mipela tu i go wantaim yu. Ol i go ausait, na go insait long wanpela sip wantu. Na dispela night ol i no kisim wanpela samting.',
        4: 'Tasol taim moning i kam nau, Jisas i sanap long nambis. Tasol ol disaipel i no save long dispela em i Jisas.',
        5: 'Nau Jisas i tokim ol, Ol pikinini, yupela i gat sampela kaikai? Ol i bekim tok long em, Nogat.',
        6: 'Na em i tokim ol, Tromoi umben long han sut sait bilong sip, na yupela bai painim pinis. Olsem na ol i tromoi umben, na nau ol i no inap long pulim dispela i kam, long wanem, ol pis i planti tru.',
        7: 'Olsem na dispela disaipel husat Jisas i laikim tru i tokim Pita, Em Bikpela. Nau taim Saimon Pita i harim long em i Bikpela, em i pasim saket bilong man bilong kisim pis bilong em i go long em, (long wanem, em i skin nating,) na em i bin tromoi em yet long biksi.',
        8: 'Na ol arapela disaipel i kam long wanpela liklik sip. (Long wanem, ol i no stap longwe long nambis, tasol samting olsem 200 kyubit,) na pulim umben wantaim ol pis.',
        9: 'Nau long taim stret long ol i kam long nambis, ol i lukim wanpela paia bilong ol sakol long dispela hap, na pis i slip antap long en, na bret.',
        10: 'Jisas i tokim ol, Bringim bilong ol dispela pis yupela i bin kisim nau.',
        11: 'Saimon Pita i go antap, na pulim umben long nambis i pulap long ol bikpela pis, 153. Na maski olgeta i planti olsem, yet umben i no bruk.',
        12: 'Jisas i tokim ol, Kam na kaikai. Na i no gat wanpela bilong ol disaipel i laik askim em, Yu husat? taim ol i save long em i Bikpela.',
        13: 'Nau Jisas i kam, na kisim bret, na givim ol, na pis wankain olsem.',
        14: 'Nau dispela em i namba tri taim long Jisas i soim em yet long ol disaipel bilong em, bihain long em i kirap bek long dai.',
        15: '¶ Olsem tasol taim ol i bin kaikai pinis, Jisas i tokim Saimon Pita, Saimon, pikinini man bilong Jonas, yu laikim mi tru moa long ol dispela? Em i tokim em, Yes, Bikpela. Yu save long mi laikim yu tru. Em i tokim em, Givim kaikai long ol pikinini sipsip bilong mi.',
        16: 'Em i tokim em gen namba tu taim, Saimon, pikinini man bilong Jonas, yu laikim mi tru? Em i tokim em, Yes, Bikpela. Yu save long mi laikim yu tru. Em i tokim em, Givim kaikai long ol sipsip bilong mi.',
        17: 'Em i tokim em namba tri taim, Saimon, pikinini man bilong Jonas, yu laikim mi tru? Pita i gat bel hevi, bilong wanem, em i tokim em namba tri taim, Yu laikim mi tru? Na em i tokim em, Bikpela, yu save long olgeta samting. Yu save long mi laikim yu tru. Jisas i tokim em, Givim kaikai long ol sipsip bilong mi.',
        18: 'Tru tumas, tru tumas, mi tokim yu, Taim yu bin stap yangpela, yu bin pasim nabaut namel bilong yu yet, na wokabaut long wanem hap we yu gat laik. Tasol taim yu bai stap lapun, yu bai stretim tupela han bilong yu i go ausait, na narapela bai pasim nabaut namel bilong yu, na karim yu long wanem hap we yu no gat laik.',
        19: 'Em i tokim dispela, bilong mekim klia long wanem kain dai em bai givim glori long God long en. Na taim em i bin toktok long dispela, em i tokim em, Bihainim mi.',
        20: '¶ Nau Pita, taim em i tanim nabaut, i lukim dispela disaipel husat Jisas i laikim tru i bihainim ol, husat tu i bin lindaun long bros bilong em long apinun kaikai, na tok, Bikpela, em i husat husat bai putim yu long han bilong birua?',
        21: 'Taim em i lukim em Pita i tokim Jisas, Bikpela, na dispela man bai mekim wanem?',
        22: 'Jisas i tokim em, Sapos mi gat laik long em i stap yet inap long mi kam, dispela em i wanem samting bilong yu? Yu bihainim mi.',
        23: 'Nau dispela tok i go ausait namel long ol brata, long dispela disaipel bai i no inap dai. Tasol Jisas i no tokim em, Em bai i no inap dai, tasol, Sapos mi gat laik long em i ken stap yet inap long mi kam, dispela em i wanem samting long yu?',
        24: 'Dispela em dispela disaipel husat i tokaut klia long ol dispela samting, na raitim ol dispela samting. Na yumi save long testimoni bilong em em i tru.',
        25: 'Na i gat planti arapela ol samting tu, dispela Jisas i mekim, long dispela, sapos ol i ken raitim ol olgeta wan wan, mi ting olsem, yes, long dispela graun em yet bai i no inap long holim ol buk ol i mas raitim. Amen.',
    },
}
